/* YAO["卦序-爻位"]，i 依序為：career、health、love、wealth、investment、marriage、lawsuit、property 的解讀 */
export const CATS = ["career","health","love","wealth","investment","marriage","lawsuit","property"];
export const YAO = {"1-1":{"name":"初九","text":"潛龍勿用","level":"L4","kw":["潛","龍","勿用","等待"],"i":["時機未到,暫時潛伏蓄積實力,不宜貿然行動","身體處於調養期,不宜劇烈運動,靜養為上","感情尚未成熟,不宜急於表白,繼續培養感情","財運平淡,不宜投機,專注本業收入","市場時機未到,持幣觀望,勿急於進場","婚姻時機未到,耐心等待更合適的對象","時機不利,暫不宜提告,繼續收集證據","房市觀望期,不急於購買,繼續尋找"]},"1-2":{"name":"九二","text":"見龍在田,利見大人","level":"L2","kw":["見龍","田","大人","顯現"],"i":["才華開始展現,遇貴人提攜,適合拜訪重要客戶或上級","健康狀況良好,適合接受專業醫師建議","感情穩定發展,適合正式介紹給雙方家長","財運轉佳,有貴人相助,收入穩定增長","適合跟隨市場領導者布局,聽取專家意見","適合認真考慮婚姻,可諮詢長輩意見","適合尋求資深律師協助,案情有轉機","適合委託信譽良好的仲介,有機會找到好房"]},"1-3":{"name":"九三","text":"君子終日乾乾,夕惕若,厲无咎","level":"L4","kw":["乾乾","惕","警惕","勤勉"],"i":["需要加倍努力保持警覺,雖有壓力但可平安度過","需要持續關注健康,作息規律,預防勝於治療","感情需要用心經營,保持警覺避免第三者介入","財務需謹慎管理,開源節流,避免不必要支出","市場波動加劇,需密切關注,嚴格停損","婚前需慎重考慮,慎重決定終身大事,不可因衝動而草率決定","訴訟進入關鍵期,需配合律師全力應對","看房需格外仔細檢查,不可大意,多方比較"]},"1-4":{"name":"九四","text":"或躍在淵,无咎","level":"L4","kw":["躍","淵","選擇","進退"],"i":["面臨重要抉擇,進可攻退可守,需審慎評估","可嘗試新的治療方式,但需諮詢專業意見","關係進入轉折點,是否更進一步需深思","有新的賺錢機會,但需評估風險後再決定","可考慮調整投資組合,但不宜過於激進","可考慮步入婚姻,需確認雙方是否真心相愛","可考慮和解或繼續訴訟,需權衡利弊","可出價議價,但保留退路,不必急於成交"]},"1-5":{"name":"九五","text":"飛龍在天,利見大人","level":"L1","kw":["飛龍","天","大人","巔峰"],"i":["事業達到高峰,決策遇到高層全力支持,大展宏圖","健康狀況極佳,精力充沛,適合挑戰目標","感情如膠似漆,雙方關係達到最佳狀態","財運亨通,收入大增,投資獲利豐厚","投資時機絕佳,市場大開,資源自動靠攏","婚姻美滿,找到理想伴侶","訴訟形勢大好,遇到有力支持,勝訴在望","絕佳購屋時機,會找到理想房產,價格合理"]},"1-6":{"name":"上九","text":"亢龍有悔","level":"L5","kw":["亢","龍","悔","過度"],"i":["位高權重但需防驕傲自滿,過剛則折,應適時收斂","過度勞累需注意休息,身體已發出警訊","過度強勢可能傷害感情,需學會退讓妥協","財務達頂峰但需見好就收,貪心恐有損失","股價已高需考慮獲利了結,繼續追高風險大","婚姻生活已穩定,無需過多變動","雖佔上風但不宜得理不饒人,適可而止為佳","房價已高不宜再追,等待回調更佳時機"]},"2-1":{"name":"初六","text":"履霜,堅冰至","level":"L7","kw":["霜","冰","警訊","漸變"],"i":["出現不利徵兆,若不改善將面臨更大困難","小病若不注意將變成大病,需及早就醫","感情出現裂痕,若不溝通將越來越嚴重","財務出現赤字警訊,需立即檢討支出","市場出現危險信號,應考慮減碼或停損","此段感情有問題跡象,不宜交往","對方開始採取不利行動,需提早應對","房屋或市場有問題跡象,需謹慎評估"]},"2-2":{"name":"六二","text":"直方大,不習无不利","level":"L2","kw":["直","方","大","正道"],"i":["行事光明正大,不用投機取巧自然順利","保持正常作息和飲食,身體自然健康","真誠相待,不需刻意討好也能順利發展","正當收入穩定,腳踏實地自然財源廣進","投資正道,長期持有績優股自然獲利","發展關係看重人品,婚姻幸福不會後悔","堅持正義和事實,無需取巧自然有利","選擇地段正、格局方正房產最為穩當"]},"2-3":{"name":"六三","text":"含章可貞,或從王事,无成有終","level":"L4","kw":["含章","王事","有終","輔佐"],"i":["適合輔佐他人,不求名但求有成,默默付出終有回報","配合醫囑治療,雖見效慢但持續就能康復","適合扮演支持者角色,不爭功但感情穩定","薪資收入穩定,雖非暴富但長期累積可觀","適合定期定額投資,不求一夕暴富穩健增長","注重實際的婚姻生活,追求平實但穩定的婚姻","配合律師策略,不急於求成最終能有結果","購買自住房,不求豪華但實用,長期保值"]},"2-4":{"name":"六四","text":"括囊,无咎无譽","level":"L4","kw":["括囊","謹慎","低調","收斂"],"i":["保持低調不表態,雖無功勞但也無過失","減少活動避免受傷,平安度過敏感期","暫時保持距離,避免過度親密或爭執","不投資不消費,保守理財確保平安","完全不操作,持現金觀望最安全","暫緩婚姻計畫,等待更好的時機","保持沉默,不做任何聲明避免不利","暫不看房,等待更明朗的時機"]},"2-5":{"name":"六五","text":"黃裳,元吉","level":"L1","kw":["黃裳","美德","謙遜","高貴"],"i":["身居高位但保持謙虛,德才兼備大獲成功","身心狀態極佳,內外兼修達到最佳狀態","內在美德吸引對方,感情美滿幸福","財富豐厚且懂得分享,財運持續亨通","投資眼光精準,獲利豐厚且穩健成長","遇到品德優良之人,找到理想伴侶極為滿意","以德服人,對方心服口服,圓滿解決","購得理想房產,環境優美價格合理"]},"2-6":{"name":"上六","text":"龍戰于野,其血玄黃","level":"L9","kw":["龍戰","血","衝突","兩敗"],"i":["與競爭對手激烈交鋒,兩敗俱傷的局面","過度消耗體力,嚴重影響健康需立即休息","感情爭吵激烈,雙方都受傷害考慮分手","財務惡鬥,可能導致重大損失","市場崩盤,多空激戰損失慘重","遇到不適合的對象引發嚴重糾紛,身心俱疲","訴訟演變成激烈對抗,雙方都付出慘痛代價","購屋糾紛嚴重,可能陷入法律訴訟"]},"3-1":{"name":"初九","text":"磐桓,利居貞,利建侯","level":"L4","kw":["磐桓","徘徊","等待","建立"],"i":["創業初期困難重重,宜守正道建立基礎","病情反覆需耐心治療,堅持正確方法","感情發展遲緩,但堅持真誠終能開花","收入不穩定,應先建立穩固財務基礎","市場不明朗,宜建立投資組合後再說","暫緩婚姻計畫,先建立需求清單再評估","訴訟剛開始,需建立完整證據和策略","購屋需謹慎,先建立明確條件再找"]},"3-2":{"name":"六二","text":"屯如邅如,乘馬班如,匪寇婚媾,女子貞不字,十年乃字","level":"L6","kw":["屯","邅","困難","延遲"],"i":["進展受阻,需要長期等待才能成功","病情需長期調養,短期難見明顯效果","感情發展極慢,需要很長時間才能修成正果","財運不佳,需長期累積才能致富","投資回報期很長,需要耐心持有","理想的對象緣分未到,需等待很久才能遇到","訴訟拖延很久,短期內難以結案","找房過程漫長,需要很久才能找到合適房產"]},"3-3":{"name":"六三","text":"即鹿无虞,惟入于林中,君子幾不如舍,往吝","level":"L7","kw":["鹿","无虞","迷失","放棄"],"i":["盲目追求目標沒有計劃,最好及早放棄","亂投醫反而更糟,應停止錯誤療法","追求不該追的人,繼續下去只會更難堪","投機賺快錢反而虧損,應及時止損","追逐熱門股沒做功課,越陷越深應退出","衝動決定與不適合的人發展關係,應儘早分手","沒有證據就提告,繼續訴訟只會更慘","看上不適合的房子,勉強購買會後悔"]},"3-4":{"name":"六四","text":"乘馬班如,求婚媾,往吉,无不利","level":"L2","kw":["乘馬","婚媾","合作","前進"],"i":["尋求合作夥伴,主動出擊將遇到成功","尋求第二意見,多方諮詢找到良醫","主動追求,表達心意,感情順利發展","尋找賺錢機會,積極行動財運亨通","尋求投資標的,主動布局將有收穫","積極發展關係,多方比較找到良緣","主動尋求和解,雙方都能接受的結果","積極看房,主動議價能找到好房"]},"3-5":{"name":"九五","text":"屯其膏,小貞吉,大貞凶","level":"L4","kw":["膏","小事","大事","限制"],"i":["小案子可做,大計畫暫緩,宜保守經營","小毛病可治,大手術需謹慎評估","小約會可行,談婚論嫁還太早","小額儲蓄可行,大額投資需避免","小額試單可以,大舉進場會虧損","小事可妥協,重大決定需三思","小額和解可談,大額求償恐難成","小坪數可考慮,豪宅別墅不適合"]},"3-6":{"name":"上六","text":"乘馬班如,泣血漣如","level":"L9","kw":["泣血","哭泣","絕望","悲傷"],"i":["事業陷入絕境,努力無果痛哭失聲","病情嚴重,治療無效極度痛苦","感情破裂,傷心欲絕痛不欲生","財務崩潰,損失慘重欲哭無淚","投資血本無歸,虧損慘重後悔莫及","遇到有嚴重問題的對象,悔恨無用極度懊悔","訴訟全面敗訴,損失慘重無力回天","購屋遭詐騙,房財兩失欲哭無淚"]},"4-1":{"name":"初六","text":"發蒙,利用刑人,用說桎梏,以往吝","level":"L5","kw":["發蒙","教育","規範","啟蒙"],"i":["需要建立規範和制度,貿然前進會有困難","需要改變不良習慣,否則健康堪憂","需要建立相處規則,否則感情難以維繫","需要建立理財紀律,否則財務混亂","需要建立投資原則,否則虧損難免","需要建立婚姻共識,否則會造成遺憾","需要遵守法律程序,否則對己不利","需要了解購屋流程,否則容易被騙"]},"4-2":{"name":"九二","text":"包蒙,吉,納婦吉,子克家","level":"L2","kw":["包蒙","包容","教導","家庭"],"i":["包容新人並悉心教導,團隊和諧效率高","包容身體的不適,耐心調養能康復","包容對方缺點,耐心經營感情美滿","包容不同收入來源,穩健累積財富","包容市場波動,長期持有獲利豐","包容對方小缺點,值得珍惜可接受","包容對方過失,和解收場皆大歡喜","包容房屋小缺點,整體條件符合可購"]},"4-3":{"name":"六三","text":"勿用取女,見金夫,不有躬,无攸利","level":"L8","kw":["勿用","見利","失身","無利"],"i":["遇見條件好的對手,盲目跟進會失去自我","看到號稱神效的療法,盲目使用反而有害","對方只看重金錢,交往下去會失去自我","看到暴利機會,盲目追求會傾家蕩產","看到飆股誘惑,盲目追高會套在高點","受到外在誘惑,盲目發展關係會陷入困境","對方財力雄厚,硬碰硬毫無勝算","看到豪宅誘惑,超出能力勉強購買會破產"]},"4-4":{"name":"六四","text":"困蒙,吝","level":"L7","kw":["困蒙","困於","無知","困難"],"i":["因為無知而陷入困境,難以突破","不懂養生之道,健康每況愈下","不懂相處之道,感情越來越僵","不懂理財之道,財務越來越糟","不懂投資之道,虧損越來越多","不懂婚姻知識,遇到不誠實的對象","不懂法律程序,訴訟越打越不利","不懂購屋知識,容易被騙上當"]},"4-5":{"name":"六五","text":"童蒙,吉","level":"L2","kw":["童蒙","虛心","學習","純真"],"i":["虛心學習請教前輩,快速成長前途光明","虛心聽從醫囑,配合治療恢復快速","保持純真初心,感情單純美好","虛心學習理財,財富穩定增長","虛心學習投資,跟對老師獲利佳","虛心請教專家,遇到理想對象","虛心聽從律師,訴訟順利進行","虛心請教專家,找到理想房產"]},"4-6":{"name":"上九","text":"擊蒙,不利為寇,利禦寇","level":"L4","kw":["擊蒙","防禦","教訓","守護"],"i":["不宜主動攻擊對手,但可防禦反擊","不宜嘗試激進療法,但可增強免疫力","不宜主動翻舊帳,但可設定底線","不宜冒險投機,但可設立停損點","不宜追高,但可逢低防守","不宜衝動決定大事,但可抵制誘惑","不宜主動提告,但可積極應訴","不宜追價搶房,但可議價守住底線"]},"5-1":{"name":"初九","text":"需于郊,利用恆,无咎","level":"L4","kw":["需","郊","等待","恆心"],"i":["在外圍等待時機,保持恆心終能成功","病情穩定,持續調養可保平安","感情需要時間培養,耐心等待有好結果","財運平穩,持續努力收入穩定","市場尚未明朗,持幣等待為佳","暫不急於發展關係,等待合適時機","訴訟需要時間,耐心配合律師","購屋不急,慢慢看慢慢挑"]},"5-2":{"name":"九二","text":"需于沙,小有言,終吉","level":"L3","kw":["沙","言語","終吉","等待"],"i":["過程中有些閒言閒語,但最終成功","治療過程有些不適,但最終康復","感情有些小爭執,但最終和好","財務有些波動,但最終獲利","投資過程有些驚嚇,但最終賺錢","婚姻過程有些麻煩,但最終滿意","訴訟過程有些爭議,但最終勝訴","購屋過程有些爭執,但最終成交"]},"5-3":{"name":"九三","text":"需于泥,致寇至","level":"L7","kw":["泥","寇","陷入","危險"],"i":["陷入困境招來敵人,處境危險","病情惡化引發併發症,需緊急處理","感情陷入泥沼引來第三者,危機重重","財務困難引來債主,壓力巨大","投資被套引來追繳,損失慘重","婚姻糾紛引來官司,麻煩不斷","訴訟不利引來反訴,雪上加霜","購屋糾紛引來法拍,可能血本無歸"]},"5-4":{"name":"六四","text":"需于血,出自穴","level":"L6","kw":["血","穴","受傷","脫困"],"i":["經歷慘烈競爭受傷,但能脫困","病情嚴重甚至出血,但能逐漸康復","感情受創傷痛不已,但能走出陰影","財務大出血損失慘重,但能止血","投資大虧血本無歸,但能及時停損","婚姻感情受騙受傷,但能挽回部分損失","訴訟失利損失慘重,但能止損","購屋被騙損失訂金,但能及時抽身"]},"5-5":{"name":"九五","text":"需于酒食,貞吉","level":"L2","kw":["酒食","宴飲","慶祝","豐盛"],"i":["事業成功值得慶祝,穩健發展大吉","身體健康精神佳,可適度享受美食","感情甜蜜如蜜,共享美好時光","財富豐盛衣食無憂,可適度享受","投資獲利豐厚,可部分獲利了結慶祝","婚姻滿意找到理想伴侶,值得慶祝","訴訟勝訴值得慶祝,圓滿收場","購得理想房產,可舉辦喬遷宴"]},"5-6":{"name":"上六","text":"入于穴,有不速之客三人來,敬之終吉","level":"L4","kw":["穴","客","敬","終吉"],"i":["遇到意外的合作機會,恭敬對待終獲成功","遇到良醫貴人相助,恭敬配合能康復","遇到意外的介紹對象,真誠相待有好結果","遇到意外的賺錢機會,謹慎把握能獲利","遇到意外的投資機會,仔細評估可進場","遇到意外的良緣,把握機會值得珍惜","遇到調解機會,誠懇配合可和解","遇到意外的好房,尊重屋主可議價成功"]},"6-1":{"name":"初六","text":"不永所事,小有言,終吉","level":"L3","kw":["不永","小言","終吉","爭執"],"i":["小糾紛及早解決,不要拖延最終順利","小病及早治療,不要拖延很快康復","小爭執及早溝通,不要冷戰感情更好","小債務及早償還,不要拖延財務健康","小虧損及早停損,不要拖延避免大虧","小缺點及早分合,不要拖延可圓滿解決","小糾紛及早和解,不要拖延訴訟費時費力","小問題及早溝通,不要拖延可順利成交"]},"6-2":{"name":"九二","text":"不克訟,歸而逋,其邑人三百戶,无眚","level":"L4","kw":["不克訟","歸","逋","逃避"],"i":["爭執打不贏,及時撤退保全實力","治療效果不佳,換個醫生或方法","爭吵無法取勝,退一步海闊天空","投資失利,及時撤資保住本金","市場不利,空手離場避免虧損","對象不合適,及早分手減少傷害","訴訟不利,撤訴和解避免更大損失","房子不適合,放棄訂金及時止損"]},"6-3":{"name":"六三","text":"食舊德,貞厲,終吉,或從王事,无成","level":"L4","kw":["食舊德","守成","无成","安分"],"i":["守住既有成果不冒進,雖無新功但保平安","維持現有療法不亂試,穩定就好","維持現狀不求改變,平淡也是幸福","守住既有財產不投機,保本就好","守住既有部位不加碼,不賺不賠","珍惜現有感情不再他求,專一為上","維持現狀不提告,息事寧人","維持現住所不換房,安居樂業"]},"6-4":{"name":"九四","text":"不克訟,復即命,渝安貞,吉","level":"L2","kw":["不克訟","復","命","改變"],"i":["爭執無法獲勝,改變策略反而成功","治療無效,改變方法反而痊癒","爭吵無益,改變態度感情更好","賺錢困難,改變方式反而獲利","虧損不斷,改變策略反而賺錢","婚姻不美滿,再婚後很幸福","訴訟不利,改為和解反而雙贏","原本看中的不適合,換個房型反而更好"]},"6-5":{"name":"九五","text":"訟,元吉","level":"L1","kw":["訟","元吉","大勝","正義"],"i":["爭執大獲全勝,正義得到伸張","病情確診治療成功,完全康復","感情爭執遇到理解,關係更進一步","財務糾紛大獲全勝,收回全部欠款","投資糾紛獲勝,拿回本金和獲利","婚姻糾紛獲勝,遇到妥善解決","訴訟大獲全勝,對方賠償所有損失","購屋糾紛獲勝,順利取得房產"]},"6-6":{"name":"上九","text":"或錫之鞶帶,終朝三褫之","level":"L7","kw":["錫","褫","得而復失","三次"],"i":["雖然遇到榮譽但很快失去,反覆不定","病情反覆好了又壞,難以根治","感情分分合合,反覆不定難以穩定","財富得而復失,反覆虧損","投資賺了又虧,來回折騰","婚姻發展關係了又退,反覆猶豫","訴訟勝了又輸,反覆上訴","購屋簽約又解約,反覆不定"]},"7-1":{"name":"初六","text":"師出以律,否臧凶","level":"L4","kw":["師","律","紀律","凶"],"i":["團隊行動必須有紀律,否則失敗","治療必須遵守醫囑,否則惡化","相處必須有規則,否則爭執不斷","理財必須有計劃,否則破產","投資必須有紀律,否則虧損","婚姻必須有條件,否則過度","訴訟必須有策略,否則敗訴","購屋必須有計劃,否則買貴"]},"7-2":{"name":"九二","text":"在師中,吉,无咎,王三錫命","level":"L1","kw":["在師中","吉","錫命","榮耀"],"i":["團隊核心成員,屢獲嘉獎,前途無量","配合醫療團隊,康復順利,醫生稱讚","雙方家庭認可,感情順利,多次祝福","收入穩定增長,屢獲獎金,財運亨通","投資核心標的,屢創新高,獲利豐厚","發展關係理想對象,屢獲好評,找到理想伴侶","訴訟順利,屢次勝訴,對方賠償","購得優質房產,屢次增值,投資成功"]},"7-3":{"name":"六三","text":"師或輿尸,凶","level":"L9","kw":["輿尸","失敗","凶","慘敗"],"i":["團隊慘敗,損失慘重,可能裁員","治療失敗,病情惡化,可能不治","感情破裂,傷痕累累,分手收場","投資慘敗,血本無歸,可能破產","投資大虧,損失慘重,本金不保","婚姻受騙,損失慘重,悔恨無用","訴訟慘敗,賠償巨額,可能破產","購屋被騙,房財兩失,血本無歸"]},"7-4":{"name":"六四","text":"師左次,无咎","level":"L4","kw":["左次","撤退","休整","无咎"],"i":["暫時撤退休整,保存實力無過失","暫停治療休養,調整狀態無大礙","暫時冷靜分開,給彼此空間無妨","暫停投資觀望,保住本金無損失","暫時空手退場,避開風險無虧損","暫緩發展關係觀望,等待時機無遺憾","暫緩提告準備,收集證據無不利","暫緩購屋觀望,等待機會無損失"]},"7-5":{"name":"六五","text":"田有禽,利執言,无咎,長子帥師,弟子輿尸,貞凶","level":"L5","kw":["田禽","長子","弟子","選擇"],"i":["用對的人成功,用錯的人失敗,選擇很重要","找對醫生康復,找錯醫生惡化,選擇很關鍵","選對對象幸福,選錯對象痛苦,眼光要準","投資對的賺錢,投資錯的虧錢,判斷要準","買對股票獲利,買錯股票虧損,研究要透","婚姻滿意,選錯對象後悔,發展關係要慎","找對律師勝訴,找錯律師敗訴,選擇要謹慎","買對房子增值,買錯房子套牢,評估要仔細"]},"7-6":{"name":"上六","text":"大君有命,開國承家,小人勿用","level":"L2","kw":["大君","開國","承家","小人勿用"],"i":["遇到重大任命建立功業,但要慎選團隊","康復成功重建健康,但要遠離不良習慣","感情修成正果成家立業,但要遠離爛桃花","創業成功建立事業,但要遠離小人合夥","投資成功建立部位,但要遠離地雷股","婚姻美滿建立家庭,但要遠離虛情假意之人","訴訟成功討回公道,但要遠離訴訟蟑螂","購屋成功建立家園,但要遠離惡鄰居"]},"8-1":{"name":"初六","text":"有孚比之,无咎,有孚盈缶,終來有它吉","level":"L2","kw":["有孚","比","誠信","終來"],"i":["真誠待人建立關係,最終帶來額外好處","誠心配合醫囑治療,最終完全康復甚至更健康","真誠對待另一半,最終感情更加深厚","誠信經營事業,最終財源滾滾而來","誠實面對市場,最終獲利超乎預期","真誠發展關係,最終遇到額外驚喜","誠實陳述事實,最終不但勝訴還獲賠償","誠信議價,最終不但成交還送裝潢"]},"8-2":{"name":"六二","text":"比之自內,貞吉","level":"L2","kw":["自內","內部","貞吉","核心"],"i":["從內部建立關係,真誠合作大吉","從內在調理身體,身心合一健康","從內心真誠相待,感情穩固美滿","從內部穩固財務,收入穩定增長","從內在價值投資,長期持有獲利","從內心需求發展關係,值得珍惜滿意","從內部證據著手,案情穩固有利","從內在需求出發,買到適合房子"]},"8-3":{"name":"六三","text":"比之匪人","level":"L7","kw":["匪人","小人","錯誤","結交"],"i":["與不當的人合作,將帶來麻煩","聽信不當醫療建議,反而有害健康","交往不當的對象,感情痛苦難耐","與不當的人合夥,財務損失慘重","投資不當的標的,虧損血本無歸","發展關係不當的婚姻,造成遺憾後悔","委託不當的律師,訴訟失利敗訴","購買不當的房產,套牢無法脫手"]},"8-4":{"name":"六四","text":"外比之,貞吉","level":"L2","kw":["外比","外部","貞吉","拓展"],"i":["向外拓展關係,開拓市場大吉","尋求外部專家,遇到良好治療","拓展社交圈,遇到理想對象","向外開拓財源,收入大幅增加","投資海外市場,獲利豐厚可期","向外尋找對象,條件適合","尋求外部支援,訴訟遇到轉機","向外地購屋,投資報酬率高"]},"8-5":{"name":"九五","text":"顯比,王用三驅,失前禽,邑人不誡,吉","level":"L2","kw":["顯比","三驅","仁慈","吉"],"i":["展現領導魅力,寬大為懷,人心歸附","採用溫和療法,身體自然康復","展現真誠魅力,對方自然親近","展現仁義經商,財富自然增長","展現長期眼光,投資自然獲利","展現理性婚姻,婚姻自然滿意","展現寬大為懷,對方自願和解","展現誠意議價,屋主自願降價"]},"8-6":{"name":"上六","text":"比之无首,凶","level":"L8","kw":["无首","無頭","混亂","凶"],"i":["團隊沒有領導,混亂無序失敗收場","治療沒有方向,病情惡化危險","感情沒有承諾,關係混亂終將分手","理財沒有計劃,財務混亂終將破產","投資沒有策略,虧損連連血本無歸","婚姻沒有規劃,造成遺憾陷入困境","訴訟沒有策略,敗訴賠償損失慘重","購屋沒有計劃,買錯房子套牢虧損"]},"9-1":{"name":"初九","text":"復自道,何其咎,吉","level":"L2","kw":["復","道","回歸","吉"],"i":["回歸正道,改正錯誤,前途光明","回歸健康生活,身體康復迅速","回歸真心相待,感情重修舊好","回歸正當收入,財務穩定增長","回歸價值投資,獲利穩健可期","回歸理性婚姻,關係穩定無虞","回歸事實真相,訴訟遇到勝利","回歸實際需求,購得合適房產"]},"9-2":{"name":"九二","text":"牽復,吉","level":"L2","kw":["牽復","拉回","挽回","吉"],"i":["被人拉回正途,感恩合作成功","被醫生拉回健康,配合治療痊癒","被對方挽回感情,珍惜復合甜蜜","被朋友提醒理財,避免損失獲利","被專家拉回投資,避開風險賺錢","被媒人提醒發展關係,遇到合適婚姻","被律師拉回策略,避免敗訴勝訴","被仲介提醒選擇,買到優質房產"]},"9-3":{"name":"九三","text":"輿說輻,夫妻反目","level":"L7","kw":["輿說輻","車壞","反目","爭執"],"i":["合作破裂,夥伴反目,事業受阻","治療中斷,醫病關係惡化,病情反覆","感情破裂,爭吵不斷,關係惡化","合夥破裂,財務糾紛,損失慘重","投資失利,與券商糾紛,虧損加劇","婚姻缺點,與長輩爭吵,分手困難","與律師不合,訴訟不利,敗訴可能","與仲介糾紛,購屋困難,可能破局"]},"9-4":{"name":"六四","text":"有孚,血去惕出,无咎","level":"L3","kw":["有孚","血去","惕出","化險"],"i":["真誠面對危機,化險為夷,轉危為安","誠心配合治療,止血成功,脫離險境","真誠溝通道歉,化解危機,感情修復","誠實面對財務,止血成功,保住本金","誠實面對虧損,停損成功,避免更大損失","誠實面對問題,分手成功,減少傷害","誠實陳述事實,和解成功,避免敗訴","誠實面對問題,退訂成功,及時止損"]},"9-5":{"name":"九五","text":"有孚攣如,富以其鄰","level":"L1","kw":["有孚","攣如","富","分享"],"i":["真誠團結,與夥伴共享成功,事業興隆","身心合一,帶動家人健康,全家安康","真誠相愛,帶動親友幸福,美滿圓滿","誠信經營,與合作夥伴共同富裕,財源廣進","誠實投資,與同好共享獲利,賺錢豐厚","誠信婚姻,遇到忠誠回饋,找到理想伴侶","誠實訴訟,遇到支持,勝訴圓滿","誠信購屋,遇到優惠,買到好房"]},"9-6":{"name":"上九","text":"既雨既處,尚德載,婦貞厲,月幾望,君子征凶","level":"L5","kw":["既雨","既處","月望","極限"],"i":["事業達頂峰,不宜再擴張,維持現狀","康復達極限,不宜過度勞累,適度休息","感情達高峰,不宜過度要求,知足常樂","財富達頂點,不宜再冒險,見好就收","獲利達高點,不宜再加碼,獲利了結","婚姻已穩定,應珍惜現有,不宜有外遇之念","已獲勝訴,不宜再上訴,適可而止","已有房產,不宜再購買,滿足現狀"]},"10-1":{"name":"初九","text":"素履,往无咎","level":"L3","kw":["素履","簡樸","本分","无咎"],"i":["保持簡樸本分,踏實工作順利發展","保持簡單生活,作息規律身體健康","保持樸實真誠,感情穩定順利發展","保持節儉美德,收入穩定財務健康","保持簡單策略,長期投資穩健獲利","保持理性婚姻,滿足基本需求無遺憾","保持誠實樸實,訴訟順利無不利","保持實際需求,購買適當房產無壓力"]},"10-2":{"name":"九二","text":"履道坦坦,幽人貞吉","level":"L2","kw":["坦坦","幽人","平坦","貞吉"],"i":["行事光明坦蕩,即使低調也能成功","心境平和坦然,身心健康大吉","相處坦誠相待,感情穩固吉祥","收入光明正大,財務坦蕩無虞","投資正道,即使低調也能獲利","婚姻坦然,不求炫耀也滿意","訴訟光明正大,即使不張揚也勝訴","購屋正當,即使低調也買到好房"]},"10-3":{"name":"六三","text":"眇能視,跛能履,履虎尾,咥人,凶,武人為于大君","level":"L8","kw":["眇","跛","虎尾","咥人","凶"],"i":["能力不足卻冒險行事,觸怒上司危險","身體虛弱卻過度勞累,病情惡化凶險","條件不足卻強求,激怒對方分手","資金不足卻投機,虧損慘重破產","知識不足卻冒進,觸發地雷虧損慘重","條件不足卻勉強發展關係,陷入困境難以自拔","證據不足卻強告,激怒法官敗訴賠償","資金不足卻硬買,法拍收場血本無歸"]},"10-4":{"name":"九四","text":"履虎尾,愬愬,終吉","level":"L3","kw":["虎尾","愬愬","恐懼","終吉"],"i":["面臨危險但保持警覺,最終化險為夷","病情危急但小心治療,最終康復成功","感情危機但謹慎處理,最終修復關係","財務危機但謹慎應對,最終轉危為安","投資危機但謹慎操作,最終反敗為勝","婚姻風險但謹慎發展關係,最終滿意無悔","訴訟危險但謹慎應對,最終勝訴成功","購屋風險但謹慎評估,最終買到好房"]},"10-5":{"name":"九五","text":"夬履,貞厲","level":"L5","kw":["夬履","果決","厲","危險"],"i":["果斷決策雖有風險,但堅持正道可保平安","果斷治療雖有風險,但遵醫囑可保安全","果斷表態雖有風險,但真誠相待可保感情","果斷投資雖有風險,但正當經營可保財富","果斷進場雖有風險,但基本面佳可保獲利","果斷發展關係雖有風險,但人品佳可保滿意","果斷提告雖有風險,但證據足可保勝訴","果斷出價雖有風險,但評估準可保成交"]},"10-6":{"name":"上九","text":"視履考祥,其旋元吉","level":"L1","kw":["視履","考祥","檢討","元吉"],"i":["回顧檢討過往,調整策略大獲成功","檢討生活習慣,改善作息完全康復","檢討相處模式,改善關係感情美滿","檢討理財方式,改善策略財富增長","檢討投資組合,調整配置獲利豐厚","檢討相處習慣,改善方式關係健康","檢討訴訟策略,調整方向勝訴圓滿","檢討購屋需求,調整條件買到理想房"]},"11-1":{"name":"初九","text":"拔茅茹,以其彙,征吉","level":"L2","kw":["拔茅茹","彙","團結","征吉"],"i":["團隊團結一致,共同進取前途光明","全面調理身體,綜合治療效果顯著","雙方家庭支持,共同努力感情美滿","多方財源匯聚,收入大幅增加","多元投資組合,分散風險獲利穩健","相親良緣多,集體相親合適踏實","證人證據齊全,集體訴訟勝訴在望","親友共同購買,集資置產成功機會大"]},"11-2":{"name":"九二","text":"包荒,用馮河,不遐遺,朋亡,得尚于中行","level":"L2","kw":["包荒","中行","包容","得尚"],"i":["包容各方意見,走中庸之道遇到重用","包容身體變化,溫和調養健康改善","包容對方缺點,平衡相處感情穩固","包容各種收入,穩健理財財富增長","包容市場波動,穩健投資長期獲利","包容婚姻缺點,理性婚姻值得珍惜","包容對方過失,和解收場雙方受益","包容房屋小缺點,理性評估買到適當房"]},"11-3":{"name":"九三","text":"無平不陂,無往不復,艱貞无咎,勿恤其孚,于食有福","level":"L4","kw":["無平不陂","往復","艱貞","有福"],"i":["事業有起有落,堅持正道終能平安,衣食無憂","病情有好有壞,持續治療終能康復,營養充足","感情有起有伏,真誠相待終能穩定,生活美滿","財運有漲有跌,穩健理財終能保本,溫飽無虞","投資有賺有賠,長期持有終能獲利,股息穩定","條件有高有低,理性婚姻終能滿意,生活無缺","訴訟有勝有負,堅持真相終能脫身,生活安穩","房價有起有落,耐心等待終能購買,居住無憂"]},"11-4":{"name":"六四","text":"翩翩,不富以其鄰,不戒以孚","level":"L2","kw":["翩翩","不富","鄰","以孚"],"i":["以真誠待人不以利誘,同事真心相助","以誠心求醫不以財求,醫生盡心治療","以真心相待不以財誘,對方真情相愛","以誠信經營不以利誘,客戶真心支持","以價值投資不以暴利,長期真實獲利","以人品為先不以條件低,長輩真心相待","以事實為證不以利誘,法官公正審判","以誠意議價不以財逼,屋主真心割愛"]},"11-5":{"name":"六五","text":"帝乙歸妹,以祉元吉","level":"L1","kw":["帝乙","歸妹","祉","元吉"],"i":["遇到高層全力支持,事業飛黃騰達","遇到名醫全力救治,完全康復健康","遇到雙方家長祝福,婚姻美滿幸福","遇到貴人全力相助,財富大幅增長","遇到專家全力指導,投資大獲成功","遇到長輩全心對待,婚姻極為滿意","遇到法官全力支持,訴訟完全勝訴","遇到屋主全力配合,購屋極為順利"]},"11-6":{"name":"上六","text":"城復于隍,勿用師,自邑告命,貞吝","level":"L6","kw":["城復隍","崩潰","勿用師","告命"],"i":["事業由盛轉衰,不宜強攻,內部整頓為上","健康由好轉壞,不宜激進治療,溫和調養","感情由熱轉冷,不宜強求,各自冷靜","財富由多轉少,不宜投機,保守理財","投資由賺轉虧,不宜加碼,停損觀望","對婚姻態度反覆,不宜衝動決定,需理性思考","由有利轉不利,不宜硬拼,和解收場","由想買轉不買,不宜勉強,另尋標的"]},"12-1":{"name":"初六","text":"拔茅茹,以其彙,貞吉亨","level":"L2","kw":["拔茅茹","彙","堅守","吉亨"],"i":["困境中團隊團結,堅守正道終能通達","病情雖重但全面治療,堅持終能康復","感情雖冷但雙方努力,堅持終能復合","財運雖差但多元開源,堅持終能轉好","投資雖虧但穩定持有,堅持終能反彈","雖缺條件但集合資源,堅持終能遇到","雖然不利但證據齊全,堅持終能翻盤","雖然困難但集資努力,堅持終能購得"]},"12-2":{"name":"六二","text":"包承,小人吉,大人否,亨","level":"L4","kw":["包承","小人吉","大人否","亨"],"i":["小職員順從上級吉,大主管抗命不利","小病順從醫囑吉,大病需轉診名醫","小事順從對方吉,大事需堅持原則","小額順從建議吉,大額需自主判斷","小額跟單吉,大額需自主研究","小事聽從介紹,大事需自己判斷","小案順從律師吉,大案需自主把關","小屋聽從仲介吉,大屋需自主評估"]},"12-3":{"name":"六三","text":"包羞","level":"L6","kw":["包羞","羞恥","忍辱","委屈"],"i":["忍受委屈和羞辱,處境艱難難以伸展","忍受病痛和不適,治療過程痛苦難耐","忍受冷落和委屈,感情痛苦考慮分手","忍受貧困和窘迫,財務困難度日艱辛","忍受虧損和套牢,投資痛苦難以脫身","忍受欺騙和不良對象,婚姻痛苦求助困難","忍受不公和屈辱,訴訟痛苦難以翻身","忍受欺詐和糾紛,購屋痛苦難以脫身"]},"12-4":{"name":"九四","text":"有命,无咎,疇離祉","level":"L3","kw":["有命","无咎","疇離","祉"],"i":["遇到任命脫離困境,同志共享福祉","遇到診斷脫離病痛,家人共享健康","遇到承諾脫離困境,雙方共享幸福","遇到機會脫離貧困,夥伴共享財富","遇到消息脫離套牢,同好共享獲利","遇到良緣脫離困境,朋友分享喜悅","遇到判決脫離糾紛,同案共享勝訴","遇到貸款脫離困境,家人共享新居"]},"12-5":{"name":"九五","text":"休否,大人吉,其亡其亡,繫于苞桑","level":"L2","kw":["休否","大人吉","苞桑","穩固"],"i":["困境結束事業轉好,但需居安思危穩固基礎","病情結束身體轉好,但需持續保養鞏固健康","危機結束感情轉好,但需持續經營穩固關係","困境結束財運轉好,但需持續理財穩固基礎","虧損結束投資轉好,但需持續研究穩固獲利","困境結束婚姻轉好,但需持續經營穩固關係","糾紛結束訴訟轉好,但需持續守法穩固基礎","困境結束購屋轉好,但需持續保養穩固資產"]},"12-6":{"name":"上九","text":"傾否,先否後喜","level":"L3","kw":["傾否","先否後喜","轉機","喜悅"],"i":["困境徹底結束,先苦後甘事業大好","病痛徹底結束,先苦後甘完全康復","危機徹底結束,先苦後甘感情美滿","困境徹底結束,先苦後甘財富增長","虧損徹底結束,先苦後甘大幅獲利","困境徹底結束,先苦後甘婚姻滿意","糾紛徹底結束,先苦後甘訴訟勝訴","困境徹底結束,先苦後甘購屋成功"]},"13-1":{"name":"初九","text":"同人于門,无咎","level":"L3","kw":["同人","門","公開","无咎"],"i":["公開合作光明正大,無私心自然順利","公開病情配合治療,無隱瞞自然康復","公開交往光明正大,無隱瞞自然順利","公開財務光明正大,無私藏自然增長","公開策略光明正大,無內線自然獲利","公開婚姻光明正大，感情正當","公開訴訟光明正大,無隱瞞自然勝訴","公開購屋光明正大,無黑箱自然成交"]},"13-2":{"name":"六二","text":"同人于宗,吝","level":"L6","kw":["同人于宗","小圈圈","狹隘","吝"],"i":["只和同派合作,格局狹小難有大成","只找熟人看病,醫術有限難以治癒","只在小圈圈交往,選擇有限難遇良緣","只和熟人交易,商機有限難以致富","只投熟悉標的,選擇有限難有大獲","只靠熟人介紹，選擇有限難覓良緣","只找熟人律師,能力有限難以勝訴","只在熟區購屋,選擇有限難有好房"]},"13-3":{"name":"九三","text":"伏戎于莽,升其高陵,三歲不興","level":"L7","kw":["伏戎","莽","高陵","不興"],"i":["設下埋伏但對手警覺,長期無法進展","隱瞞病情不敢就醫,長期無法康復","隱藏心意不敢表白,長期無法進展","隱藏收入逃稅漏稅,長期提心吊膽","隱藏虧損不敢認賠,長期套牢難脫","隱藏婚姻不敢讓人知,長期愧疚難安","隱藏證據不敢提告,長期委屈難伸","隱藏產權不敢過戶,長期無法使用"]},"13-4":{"name":"九四","text":"乘其墉,弗克攻,吉","level":"L3","kw":["乘墉","弗克攻","知難而退","吉"],"i":["評估對手實力,知難而退保全實力","評估病情嚴重,轉診名醫正確決定","評估對方條件,知難而退避免傷害","評估投資風險,知難而退保住本金","評估標的風險,知難而退避免虧損","評估婚姻條件,知難而退避免過度","評估訴訟勝算,知難而退避免敗訴","評估房價太高,知難而退避免套牢"]},"13-5":{"name":"九五","text":"同人,先號咷而後笑,大師克相遇","level":"L2","kw":["號咷","後笑","大師克","相遇"],"i":["合作過程雖艱辛,但最終成功喜悅","治療過程雖痛苦,但最終康復歡喜","相戀過程雖波折,但最終結合幸福","創業過程雖辛苦,但最終成功富裕","投資過程雖驚險,但最終獲利豐厚","婚姻過程雖麻煩,但最終滿意開心","訴訟過程雖痛苦,但最終勝訴慶祝","購屋過程雖艱辛,但最終成交喜悅"]},"13-6":{"name":"上九","text":"同人于郊,无悔","level":"L4","kw":["同人于郊","遠郊","無成","无悔"],"i":["合作對象遠在郊外,雖無大成但不後悔","求醫地點遠在郊外,雖不便但無遺憾","對象遠在他鄉,雖難見面但無悔恨","財源遠在外地,雖不豐厚但無遺憾","投資海外市場,雖不豐收但無後悔","婚姻遠在他鄉,雖不方便但無遺憾","訴訟遠在外地,雖不便但無遺憾","購屋遠在郊區,雖不便但無後悔"]},"14-1":{"name":"初九","text":"無交害,匪咎,艱則无咎","level":"L3","kw":["無交害","艱","无咎","謹慎"],"i":["初期謹慎不與人結怨,雖艱辛但平安","初期謹慎避免感染,雖辛苦但健康","初期謹慎不濫情,雖孤單但無害","初期謹慎不亂投資,雖清貧但保本","初期謹慎觀望,雖無獲利但無虧損","初期謹慎不亂發展關係,雖雖未成婚但無負擔","初期謹慎不樹敵,雖無援但無害","初期謹慎不急買,雖無房但無債"]},"14-2":{"name":"九二","text":"大車以載,有攸往,无咎","level":"L2","kw":["大車","載","有攸往","承載"],"i":["能力強可承擔重任,放心前進無妨","體力好可承受治療,積極配合無礙","能力強可承擔家庭,放心結婚無妨","財力強可承擔投資,放心進場無虞","資金足可承擔風險,放心加碼無妨","條件足夠可承擔,放心發展關係無礙","證據足可承擔訴訟,放心提告無虞","財力足可承擔房貸,放心購買無妨"]},"14-3":{"name":"九三","text":"公用亨于天子,小人弗克","level":"L2","kw":["公","天子","小人弗克","大格局"],"i":["有大格局能獲高層賞識,小人做不到","有大決心能戰勝病魔,小病小痛不算什麼","有大愛心能感動對方,小心機不管用","有大視野能創造財富,小聰明賺不了大錢","有大格局能長期獲利,短線投機賺不久","有大眼光能婚姻,好高騖遠難覓良緣","有大義名分能勝訴,小動作不管用","有大眼光能買對房,貪便宜買不到好房"]},"14-4":{"name":"九四","text":"匪其彭,无咎","level":"L3","kw":["匪其彭","不炫耀","謙虛","无咎"],"i":["有實力但不炫耀,低調做事平安順利","康復了但不逞強,持續保養健康穩定","有對象但不炫耀,低調交往感情穩定","有財富但不炫耀,低調理財平安無事","有獲利但不炫耀,低調操作持續賺錢","有良緣但不炫耀,低調使用避免眼紅","有證據但不炫耀,低調應訴順利勝訴","有房產但不炫耀,低調居住平安無事"]},"14-5":{"name":"六五","text":"厥孚交如,威如,吉","level":"L1","kw":["厥孚","交如","威如","吉"],"i":["真誠待人建立威信,上下一心事業大成","真誠配合建立信任,醫病合作完全康復","真誠相待建立信任,雙方相敬如賓幸福","真誠經營建立信譽,客戶信賴財源廣進","真誠研究建立信心,長期持有獲利豐厚","真誠交易建立信任,長輩良緣找到理想伴侶","真誠陳述建立信用,法官信任完全勝訴","真誠議價建立信任,屋主割愛價格優惠"]},"14-6":{"name":"上九","text":"自天祐之,吉无不利","level":"L1","kw":["自天祐","吉","无不利","天佑"],"i":["天佑神助,事業一帆風順萬事大吉","天佑神助,身體完全康復健康無比","天佑神助,感情美滿幸福白頭偕老","天佑神助,財富豐厚衣食無憂","天佑神助,投資大獲全勝財富自由","天佑神助,婚姻極為滿意找到理想伴侶","天佑神助,訴訟完全勝訴對方賠償","天佑神助,購得理想房產增值可期"]},"15-1":{"name":"初六","text":"謙謙君子,用涉大川,吉","level":"L2","kw":["謙謙","君子","涉大川","吉"],"i":["謙虛謹慎,即使面對大挑戰也能成功","謙虛聽從醫囑,即使大病也能康復","謙虛對待對方,即使困難也能克服","謙虛經營事業,即使困難也能致富","謙虛學習投資,即使風險也能獲利","謙虛請教專家,即使貴重也能發展關係對","謙虛配合律師,即使困難也能勝訴","謙虛請教長輩,即使困難也能覓得良緣房"]},"15-2":{"name":"六二","text":"鳴謙,貞吉","level":"L2","kw":["鳴謙","聲名","貞吉","美譽"],"i":["謙虛有名,美譽遠播事業成功","謙虛配合,醫生稱讚康復迅速","謙虛相待,親友稱讚感情美滿","謙虛經營,客戶稱讚生意興隆","謙虛學習,專家稱讚投資得當","謙虛待人,長輩稱讚態度良好","謙虛陳述,法官稱讚態度良好","謙虛議價,仲介稱讚誠意十足"]},"15-3":{"name":"九三","text":"勞謙,君子有終,吉","level":"L2","kw":["勞謙","有終","吉","功成"],"i":["辛勤工作又謙虛,最終功成名就","努力養生又謙虛,最終完全康復","努力經營又謙虛,最終修成正果","努力創業又謙虛,最終財富自由","努力研究又謙虛,最終投資成功","努力比較又謙虛,最終遇到良緣","努力準備又謙虛,最終完全勝訴","努力找房又謙虛,最終買到好房"]},"15-4":{"name":"六四","text":"無不利,撝謙","level":"L2","kw":["無不利","撝謙","揮灑","謙遜"],"i":["有能力但更謙虛,做什麼都順利","康復了但仍謙虛,身體越來越好","有對象但仍謙虛,感情越來越好","有錢了但仍謙虛,財富越來越多","賺錢了但仍謙虛,獲利越來越多","有能力但仍謙虛,婚姻越來越精明","勝訴了但仍謙虛,對方心服口服","有房了但仍謙虛,資產越來越多"]},"15-5":{"name":"六五","text":"不富以其鄰,利用侵伐,无不利","level":"L2","kw":["不富","鄰","侵伐","无不利"],"i":["不靠財富而靠人心,適合主動出擊成功","不靠金錢而靠養生,適合積極治療康復","不靠財富而靠真心,適合主動追求成功","不靠投機而靠誠信,適合主動拓展獲利","不靠內線而靠研究,適合主動進場賺錢","不靠斤斤計較而靠真心,適合主動詢問良緣","不靠關係而靠證據,適合主動提告勝訴","不靠關係而靠誠意,適合主動議價成功"]},"15-6":{"name":"上六","text":"鳴謙,利用行師,征邑國","level":"L2","kw":["鳴謙","行師","征邑國","利"],"i":["謙虛有名,適合大展身手拓展事業","謙虛有名,適合接受挑戰恢復健康","謙虛有名,適合公開交往建立家庭","謙虛有名,適合擴大經營增加財富","謙虛有名,適合增加投資擴大獲利","謙虛有名,適合大量發展關係遇到良緣","謙虛有名,適合提告維權完全勝訴","謙虛有名,適合購買房產建立資產"]},"16-1":{"name":"初六","text":"鳴豫,凶","level":"L8","kw":["鳴豫","炫耀","凶","招災"],"i":["炫耀成就招來嫉妒,樹敵太多危險","炫耀健康過度勞累,身體出問題","炫耀感情招來眼紅,第三者介入","炫耀財富招來�覬覦,破財招災","炫耀獲利招來跟風,反而套牢","炫耀婚姻招來眼紅,引起糾紛","炫耀勝訴招來反撲,再被告","炫耀購屋招來眼紅,引起麻煩"]},"16-2":{"name":"六二","text":"介于石,不終日,貞吉","level":"L2","kw":["介于石","堅定","貞吉","不動搖"],"i":["立場堅定不被誘惑,事業穩健成功","意志堅定配合治療,很快就能康復","立場堅定不被誘惑,感情忠貞美滿","原則堅定不被誘惑,財務穩健增長","策略堅定不被誘惑,投資穩健獲利","立場堅定不被甜言蜜語,婚姻理性無悔","立場堅定不被威脅,訴訟穩健勝訴","立場堅定不被哄騙,購屋穩健成功"]},"16-3":{"name":"六三","text":"盱豫,悔,遲有悔","level":"L6","kw":["盱豫","猶豫","悔","遲疑"],"i":["猶豫不決錯失良機,後悔莫及","猶豫不決延誤就醫,病情惡化","猶豫不決錯失良緣,後悔終生","猶豫不決錯失商機,財富流失","猶豫不決錯失時機,錯過獲利","猶豫不決錯失良緣,被人搶先","猶豫不決錯失時效,無法提告","猶豫不決錯失好房,被人買走"]},"16-4":{"name":"九四","text":"由豫,大有得,勿疑,朋盍簪","level":"L1","kw":["由豫","大有得","朋盍簪","歡聚"],"i":["領導團隊遇到大成功,夥伴歡聚慶祝","主導治療遇到大康復,醫生稱讚歡喜","主導關係遇到大幸福,親友歡聚祝賀","主導事業遇到大財富,合夥歡聚分紅","主導投資遇到大獲利,同好歡聚慶祝","主導相親遇到良緣,朋友歡聚分享","主導訴訟遇到大勝訴,同案歡聚慶祝","主導購屋遇到好房產,家人歡聚喬遷"]},"16-5":{"name":"六五","text":"貞疾,恆不死","level":"L6","kw":["貞疾","長期病","恆不死","纏綿"],"i":["事業長期低迷,雖不倒閉但難突破","慢性病纏身,雖不致命但難痊癒","感情長期冷淡,雖不分手但無熱情","財務長期拮据,雖不破產但難富裕","投資長期套牢,雖不腰斬但難獲利","婚姻長期囤積,雖不過期但難使用","訴訟長期拖延,雖不敗訴但難結案","房產長期滯銷,雖不跌價但難脫手"]},"16-6":{"name":"上六","text":"冥豫,成有渝,无咎","level":"L4","kw":["冥豫","昏沉","渝","改變"],"i":["沉溺享樂迷失方向,及時改變可保平安","沉溺享樂損害健康,及時改變可保健康","沉溺享樂忽略對方,及時改變可保感情","沉溺享樂揮霍無度,及時改變可保財富","沉溺享樂疏於研究,及時改變可保獲利","沉溺婚姻陷入困境,及時改變可保護自己","沉溺享樂疏於準備,及時改變可保勝訴","沉溺享樂疏於保養,及時改變可保資產"]},"17-1":{"name":"初九","text":"官有渝,貞吉,出門交有功","level":"L2","kw":["官有渝","改變","交","有功"],"i":["改變工作方向,向外發展建立人脈有成","改變治療方法,多方諮詢尋求良醫有效","改變交友圈,主動社交認識新對象成功","改變賺錢方式,拓展客源增加收入有成","改變投資策略,多元配置分散風險獲利","改變婚姻習慣,多方比較找到良緣合適","改變訴訟策略,尋求外援找到證據有利","改變購屋區域,擴大範圍找到好房成功"]},"17-2":{"name":"六二","text":"係小子,失丈夫","level":"L7","kw":["係小子","失丈夫","捨本逐末","錯誤"],"i":["跟隨小人失去貴人,捨本逐末損失慘重","相信庸醫失去名醫,延誤治療病情惡化","選擇渣男失去良緣,後悔莫及痛苦不堪","追求小利失去大財,因小失大損失慘重","投資垃圾股失去績優股,虧損慘重","貪圖條件低失去人品,遇到不良對象後悔莫及","委託爛律師失去好律師,敗訴收場","貪圖便宜失去好房,買到爛屋後悔不已"]},"17-3":{"name":"六三","text":"係丈夫,失小子,隨有求得,利居貞","level":"L2","kw":["係丈夫","失小子","有求得","利居貞"],"i":["跟隨貴人捨棄小人,堅守正道必有所得","追隨名醫放棄庸醫,堅持治療必能康復","選擇良緣放棄爛桃花,堅守真愛必能幸福","追求正財放棄偏財,堅守正道必能致富","投資績優股放棄投機,堅持價值必能獲利","追求人品放棄條件低,堅持原則必能滿意","委託好律師放棄爛律師,堅持正義必能勝訴","追求好房放棄便宜屋,堅持標準必能滿意"]},"17-4":{"name":"九四","text":"隨有獲,貞凶,有孚在道,以明,何咎","level":"L5","kw":["隨有獲","貞凶","有孚在道","明"],"i":["跟隨能獲利但需警惕,堅持正道才能長久","治療有效但需警惕,堅持養生才能持久","交往甜蜜但需警惕,堅持真誠才能長久","賺錢容易但需警惕,堅持正道才能持久","獲利豐厚但需警惕,堅持原則才能長久","婚姻滿意但需警惕,堅持理性才能持久","訴訟順利但需警惕,堅持證據才能勝訴","購屋順利但需警惕,堅持檢查才能安心"]},"17-5":{"name":"九五","text":"孚于嘉,吉","level":"L1","kw":["孚于嘉","誠信","美善","吉"],"i":["真誠追隨優秀領導,事業大獲成功","真誠配合優秀醫師,完全康復健康","真誠對待優秀對象,感情美滿幸福","真誠經營優質事業,財富豐厚富裕","真誠研究優質標的,投資大獲成功","真誠發展關係理想對象,找到理想伴侶滿意","真誠委託優秀律師,訴訟完全勝訴","真誠購買優質房產,增值可期滿意"]},"17-6":{"name":"上六","text":"拘係之,乃從維之,王用亨于西山","level":"L2","kw":["拘係","從維","王用亨","西山"],"i":["被重用委以重任,遇到最高榮譽","被專家特別照顧,遇到最佳治療","被對方深深愛著,遇到最大幸福","被貴人提拔重用,遇到最大財富","被專家特別指導,遇到最大獲利","被長輩特別服務,遇到最大良緣","被法官特別重視,遇到最佳判決","被屋主特別割愛,遇到最好房產"]},"18-1":{"name":"初六","text":"幹父之蠱,有子,考无咎,厲終吉","level":"L3","kw":["幹父蠱","修正","考","終吉"],"i":["修正前人錯誤,雖困難但最終成功","修正不良習慣,雖辛苦但最終康復","修正相處問題,雖艱難但最終和好","修正理財錯誤,雖辛苦但最終致富","修正投資錯誤,雖虧損但最終獲利","修正相處方式,雖困難但最終健康","修正訴訟策略,雖艱難但最終勝訴","修正購屋錯誤,雖麻煩但最終滿意"]},"18-2":{"name":"九二","text":"幹母之蠱,不可貞","level":"L5","kw":["幹母蠱","不可貞","溫和","謹慎"],"i":["修正上級錯誤需謹慎,不可太強硬","修正醫囑需謹慎,不可自作主張","修正對方錯誤需謹慎,不可太強勢","修正財務需謹慎,不可太激進","修正策略需謹慎,不可太冒險","分合需謹慎,不可態度不佳","修正訴訟需謹慎,不可太咄咄逼人","修正合約需謹慎,不可太強硬"]},"18-3":{"name":"九三","text":"幹父之蠱,小有悔,无大咎","level":"L4","kw":["幹父蠱","小悔","无大咎","過猛"],"i":["修正錯誤稍嫌過猛,雖有小遺憾但無大礙","治療稍嫌激進,雖有小副作用但無大礙","改變稍嫌過度,雖有小爭執但無大礙","改革稍嫌激烈,雖有小損失但無大礙","調整稍嫌急躁,雖有小虧損但無大礙","分手稍嫌強硬,雖有小不開心但無大礙","策略稍嫌激進,雖有小波折但無大礙","議價稍嫌過低,雖有小摩擦但無大礙"]},"18-4":{"name":"六四","text":"裕父之蠱,往見吝","level":"L6","kw":["裕父蠱","寬容","往見吝","縱容"],"i":["過度寬容錯誤,繼續下去會更糟","過度縱容病痛,繼續下去會惡化","過度縱容對方,繼續下去會更難相處","過度寬容浪費,繼續下去會破產","過度寬容虧損,繼續下去會血本無歸","過度寬容缺點,繼續下去會遇到更多不好的對象","過度寬容對方,繼續下去會更不利","過度寬容缺點,繼續下去會買到爛屋"]},"18-5":{"name":"六五","text":"幹父之蠱,用譽","level":"L2","kw":["幹父蠱","用譽","美譽","成功"],"i":["成功修正前人錯誤,遇到讚譽","成功改善健康問題,遇到稱讚","成功改善感情問題,遇到認可","成功改善財務問題,遇到肯定","成功調整投資策略,遇到推崇","成功改善相處方式,遇到讚賞","成功調整訴訟策略,遇到勝訴","成功改善購屋決策,遇到滿意"]},"18-6":{"name":"上九","text":"不事王侯,高尚其事","level":"L3","kw":["不事王侯","高尚","獨立","清高"],"i":["不為名利工作,追求理想志業可敬","不依賴藥物,自然養生值得學習","不為條件交往,追求真愛令人敬佩","不為金錢奔波,追求理想生活自在","不為暴利投機,追求價值投資穩健","不為虛榮婚姻,追求實用理性明智","不為金錢訴訟,追求正義值得尊敬","不為投資購屋,追求居住品質實在"]},"19-1":{"name":"初九","text":"咸臨,貞吉","level":"L2","kw":["咸臨","感應","貞吉","真誠"],"i":["真誠對待下屬,感應互通事業成功","真誠配合治療,醫病互信康復迅速","真誠對待對方,心意相通感情美滿","真誠對待客戶,互相信任生意興隆","真誠研究市場,順應趨勢獲利豐厚","真誠對待長輩,互相尊重相處愉快","真誠陳述事實,法官信任順利勝訴","真誠對待屋主,互相信任交易順利"]},"19-2":{"name":"九二","text":"咸臨,吉,无不利","level":"L1","kw":["咸臨","吉","无不利","全面"],"i":["真誠領導全面成功,做什麼都順利","真誠養生全面健康,身心都康泰","真誠相愛全面幸福,事事都美滿","真誠經營全面成功,財源滾滾來","真誠投資全面獲利,處處都賺錢","真誠相待全面滿意,樣樣都如意","真誠訴訟全面勝利,完全大勝訴","真誠購屋全面滿意,各方面都好"]},"19-3":{"name":"六三","text":"甘臨,无攸利,既憂之,无咎","level":"L4","kw":["甘臨","甜言","憂","无咎"],"i":["過度討好下屬無益,及時警覺可保平安","過度依賴藥物無益,及時警覺可保健康","過度討好對方無益,及時警覺可保感情","過度討好客戶無益,及時警覺可保利潤","過度樂觀無益,及時警覺可保獲利","過度相信甜言蜜語無益,及時警覺可保護自己","過度相信對方無益,及時警覺可保勝訴","過度相信仲介無益,及時警覺可保權益"]},"19-4":{"name":"六四","text":"至臨,无咎","level":"L3","kw":["至臨","親臨","无咎","盡心"],"i":["親自督導盡心盡力,事業順利無過失","親自照顧用心養生,身體健康無問題","親自經營用心相處,感情穩定無波折","親自管理用心經營,財務健全無虧損","親自研究用心分析,投資穩健無虧損","親自挑選用心比較,婚姻滿意無後悔","親自出庭用心準備,訴訟順利無敗訴","親自看房用心評估,購屋滿意無遺憾"]},"19-5":{"name":"六五","text":"知臨,大君之宜,吉","level":"L1","kw":["知臨","智慧","大君","吉"],"i":["以智慧領導如君王,事業大獲成功","以智慧養生如聖賢,身體完全康復","以智慧相處如賢者,感情美滿幸福","以智慧經營如商聖,財富豐厚富裕","以智慧投資如大師,獲利極為豐厚","以智慧婚姻如專家,找到理想伴侶滿意","以智慧訴訟如律師,完全勝訴成功","以智慧購屋如達人,買到最佳房產"]},"19-6":{"name":"上六","text":"敦臨,吉,无咎","level":"L2","kw":["敦臨","厚道","吉","无咎"],"i":["以厚道待人,深得人心事業成功","以厚道養生,身心安康健康長壽","以厚道待人,深受愛戴感情美滿","以厚道經商,客戶信賴財源廣進","以厚道投資,穩健踏實長期獲利","以厚道待人,長輩敬重良緣不斷","以厚道訴訟,法官敬重順利勝訴","以厚道購屋,屋主割愛價格優惠"]},"20-1":{"name":"初六","text":"童觀,小人无咎,君子吝","level":"L5","kw":["童觀","幼稚","小人","君子吝"],"i":["見識淺薄,小職員無妨,主管則不適任","知識不足,小病無妨,大病需專業","經驗不足,年輕無妨,成熟則需改進","理財幼稚,小額無妨,大額則危險","投資幼稚,小錢無妨,大錢則虧損","婚姻幼稚,小事無妨,大事則後悔","法律幼稚,小案無妨,大案則敗訴","購屋幼稚,小屋無妨,大屋則失算"]},"20-2":{"name":"六二","text":"闚觀,利女貞","level":"L5","kw":["闚觀","窺視","狹隘","利女貞"],"i":["眼光狹窄只看表面,適合執行不適合決策","只看症狀不看根本,適合保養不適合治病","只看外表不看內在,適合交往不適合結婚","只看小利不看大局,適合儲蓄不適合投資","只看短線不看長期,適合小額不適合大額","只看條件不看人品,適合小事不適合大事","只看表面不看實質,適合和解不適合硬拼","只看價格不看品質,適合小屋不適合大屋"]},"20-3":{"name":"六三","text":"觀我生,進退","level":"L4","kw":["觀我生","反省","進退","抉擇"],"i":["觀察自己表現,決定進退去留","觀察身體狀況,決定治療方向","觀察感情狀況,決定進退關係","觀察財務狀況,決定投資策略","觀察投資績效,決定加減碼","觀察婚姻習慣,決定節制程度","觀察訴訟形勢,決定和解或繼續","觀察房市狀況,決定買賣時機"]},"20-4":{"name":"六四","text":"觀國之光,利用賓于王","level":"L2","kw":["觀國光","見識","賓于王","貴賓"],"i":["見識廣博受到重用,成為高層座上賓","見識廣博找到名醫,受到特別照顧","見識廣博受到青睞,成為理想對象","見識廣博受到重用,成為合作夥伴","見識廣博受到推崇,成為投資顧問","見識廣博受到尊重,成為VIP客戶","見識廣博受到重視,成為重要證人","見識廣博受到重視,遇到優先購買權"]},"20-5":{"name":"九五","text":"觀我生,君子无咎","level":"L3","kw":["觀我生","反省","君子","无咎"],"i":["經常反省自己,不斷改進無過失","經常檢查身體,預防疾病保健康","經常反省相處,改善關係保和諧","經常檢討財務,改善策略保獲利","經常檢討績效,調整配置保收益","經常檢討婚姻,改善習慣保護自己","經常檢討策略,調整方向保勝訴","經常檢討需求,調整標準保滿意"]},"20-6":{"name":"上九","text":"觀其生,君子无咎","level":"L3","kw":["觀其生","觀察他人","君子","无咎"],"i":["觀察他人表現,學習改進無過失","觀察他人經驗,學習養生保健康","觀察他人關係,學習相處保和諧","觀察他人經營,學習方法保獲利","觀察他人策略,學習技巧保收益","觀察他人感情,學習理性保護自己","觀察他人案例,學習策略保勝訴","觀察他人經驗,學習評估保滿意"]},"21-1":{"name":"初九","text":"屨校滅趾,无咎","level":"L4","kw":["屨校","滅趾","小懲","无咎"],"i":["初犯小錯受小懲,記取教訓無大礙","初期小病即治療,及早處理無大礙","初次爭執即和解,及時溝通無大礙","初期虧損即停損,及時處理無大礙","初期套牢即認賠,及時停損無大礙","初次不滿即分手,及時處理無大礙","初期不利即和解,及時處理無大礙","初期發現問題即處理,及時修繕無大礙"]},"21-2":{"name":"六二","text":"噬膚滅鼻,无咎","level":"L4","kw":["噬膚","滅鼻","中度懲罰","无咎"],"i":["中度錯誤受懲罰,記取教訓可改過","中度病痛需治療,配合醫囑可康復","中度爭執需溝通,真誠道歉可和好","中度虧損需檢討,調整策略可回本","中度套牢需調整,改變策略可解套","中度不滿需處理,積極溝通可解決","中度不利需調整,改變策略可翻盤","中度問題需修繕,積極處理可解決"]},"21-3":{"name":"六三","text":"噬腊肉,遇毒,小吝,无咎","level":"L5","kw":["噬腊肉","遇毒","小吝","无咎"],"i":["處理棘手問題遇困難,雖難堪但能解決","治療頑疾遇副作用,雖不適但能康復","處理感情問題遇阻力,雖痛苦但能和好","處理財務問題遇困難,雖虧損但能回本","處理套牢遇困難,雖虧損但能解套","處理糾紛遇困難,雖麻煩但能解決","處理訴訟遇困難,雖艱辛但能勝訴","處理問題遇困難,雖麻煩但能修好"]},"21-4":{"name":"九四","text":"噬乾胏,得金矢,利艱貞,吉","level":"L3","kw":["噬乾胏","得金矢","艱貞","吉"],"i":["處理困難問題,堅持正道最終成功","治療頑疾,堅持治療最終康復","處理感情危機,堅持真誠最終和好","處理財務危機,堅持正道最終獲利","處理投資困境,堅持原則最終解套","處理婚姻糾紛,堅持權益最終解決","處理訴訟困境,堅持正義最終勝訴","處理房屋問題,堅持權益最終解決"]},"21-5":{"name":"六五","text":"噬乾肉,得黃金,貞厲,无咎","level":"L3","kw":["噬乾肉","得黃金","貞厲","无咎"],"i":["處理重大問題遇到成果,雖危險但無過失","治療重病遇到康復,雖辛苦但無大礙","處理重大危機遇到和解,雖痛苦但能維繫","處理重大虧損遇到回本,雖危險但無損失","處理重大套牢遇到解套,雖危險但無虧損","處理重大糾紛獲得補償,雖麻煩但無損失","處理重大訴訟遇到勝訴,雖危險但無敗訴","處理重大問題遇到解決,雖麻煩但無損失"]},"21-6":{"name":"上九","text":"何校滅耳,凶","level":"L8","kw":["何校","滅耳","重懲","凶"],"i":["嚴重錯誤受重懲,可能被開除","嚴重疾病難治療,可能不治","嚴重背叛難原諒,可能分手","嚴重虧損難彌補,可能破產","嚴重套牢難解套,可能血本無歸","嚴重糾紛難解決,可能訴訟敗訴","嚴重敗訴難翻身,可能傾家蕩產","嚴重問題難解決,可能房財兩失"]},"22-1":{"name":"初九","text":"賁其趾,舍車而徒","level":"L3","kw":["賁其趾","舍車徒步","樸實","健康"],"i":["注重基礎不求虛榮,腳踏實地穩健發展","注重基礎養生,少依賴藥物多運動","注重內在不重外表,真誠相待感情穩固","注重實際不慕虛榮,穩健累積財富增長","注重價值不追熱門,穩健投資長期獲利","注重實際不求名門,理性婚姻關係健康","注重實質不重形式,實事求是順利勝訴","注重實用不求豪華,理性購屋居住舒適"]},"22-2":{"name":"六二","text":"賁其須","level":"L4","kw":["賁其須","裝飾","表面","跟隨"],"i":["只重表面裝飾,缺乏實質內涵","只重外表保養,忽略內在調理","只重外表打扮,忽略內在修養","只重表面風光,忽略實際獲利","只重表面數字,忽略實質價值","只重外表,忽略實際人品","只重表面文章,忽略實質證據","只重外表裝潢,忽略實際品質"]},"22-3":{"name":"九三","text":"賁如,濡如,永貞吉","level":"L2","kw":["賁如","濡如","永貞","吉"],"i":["內外兼修恰到好處,長期堅持必獲成功","內外兼顧恰到好處,長期保養身體健康","內外兼美恰到好處,長期相守感情美滿","內外兼顧恰到好處,長期經營財富增長","內外兼顧恰到好處,長期持有獲利豐厚","內外兼顧恰到好處,長期使用找到理想伴侶","內外兼顧恰到好處,長期堅持順利勝訴","內外兼顧恰到好處,長期居住舒適滿意"]},"22-4":{"name":"六四","text":"賁如皤如,白馬翰如,匪寇婚媾","level":"L3","kw":["賁如皤如","白馬","婚媾","真誠"],"i":["外表樸素內心真誠,終獲貴人相助","外表平凡身體健康,自然養生有效","外表樸實內心真誠,終獲真愛幸福","外表樸素誠信經營,終獲客戶信賴","外表低調紮實研究,終獲豐厚利潤","外表樸素理性婚姻,終獲找到理想伴侶","外表謙遜據理力爭,終獲公正判決","外表樸素實用為主,終獲滿意房產"]},"22-5":{"name":"六五","text":"賁于丘園,束帛戔戔,吝,終吉","level":"L3","kw":["賁丘園","束帛","吝","終吉"],"i":["雖然資源有限略顯寒酸,但最終成功","雖然條件有限略顯簡陋,但最終康復","雖然條件有限略顯樸素,但最終幸福","雖然資金有限略顯拮据,但最終致富","雖然本金有限略顯不足,但最終獲利","雖然條件有限略顯寒酸,但最終滿意","雖然資源有限略顯不足,但最終勝訴","雖然資金有限略顯不足,但最終購得"]},"22-6":{"name":"上九","text":"白賁,无咎","level":"L3","kw":["白賁","純樸","无咎","返璞"],"i":["返璞歸真不事雕琢,自然成功無過失","返璞歸真不事藥物,自然養生保健康","返璞歸真不事浪漫,真誠相待保和諧","返璞歸真不事浮華,誠信經營保獲利","返璞歸真不事投機,價值投資保收益","返璞歸真不事奢華,理性婚姻保護自己","返璞歸真不事技巧,實事求是保勝訴","返璞歸真不事豪華,實用為主保滿意"]},"23-1":{"name":"初六","text":"剝床以足,蔑貞,凶","level":"L8","kw":["剝床","足","基礎崩壞","凶"],"i":["事業根基開始崩壞,非常危險","健康基礎開始惡化,病情嚴重","感情基礎開始動搖,關係危險","財務基礎開始崩潰,破產危機","投資基礎開始崩盤,虧損嚴重","婚姻基礎開始失控,關係危機","訴訟基礎開始崩壞,敗訴危險","房產基礎開始受損,價值下跌"]},"23-2":{"name":"六二","text":"剝床以辨,蔑貞,凶","level":"L8","kw":["剝床","辨","中層崩壞","凶"],"i":["事業中層崩壞,情況惡化","健康中度惡化,需緊急治療","感情中度崩壞,分手危機","財務中度崩潰,嚴重虧損","投資中度崩盤,損失慘重","婚姻中度失控,陷入困境","訴訟中度崩壞,敗訴在即","房產中度受損,大幅貶值"]},"23-3":{"name":"六三","text":"剝之,无咎","level":"L4","kw":["剝之","脫離","无咎","及時"],"i":["及時脫離崩壞組織,可保平安","及時改變不良習慣,可保健康","及時結束不良關係,可保清白","及時退出虧損事業,可保本金","及時賣出套牢股票,可保部分本金","及時停止過度投入,可保護自己","及時撤訴或和解,可保顏面","及時脫手問題房產,可減少損失"]},"23-4":{"name":"六四","text":"剝床以膚,凶","level":"L9","kw":["剝床","膚","深層崩壞","凶"],"i":["事業深層崩壞,傷及核心人員","健康深度惡化,傷及重要器官","感情深度崩壞,傷及自尊心","財務深度崩潰,傷及生活基本","投資深度崩盤,本金幾乎全失","婚姻深度失控,傷及信用崩潰","訴訟深度崩壞,傾家蕩產","房產深度受損,幾乎無價值"]},"23-5":{"name":"六五","text":"貫魚,以宮人寵,无不利","level":"L2","kw":["貫魚","宮人寵","恩寵","无不利"],"i":["在崩壞中遇到重用,轉危為安","在病痛中遇到良醫,轉危為安","在危機中遇到真愛,轉危為安","在虧損中遇到轉機,轉虧為盈","在套牢中遇到解套,轉虧為盈","在困境中遇到援助,轉危為安","在敗訴中遇到轉機,轉敗為勝","在貶值中遇到買家,及時脫手"]},"23-6":{"name":"上九","text":"碩果不食,君子得輿,小人剝廬","level":"L3","kw":["碩果","得輿","剝廬","保存"],"i":["保存實力如君子得車,小人則失去一切","保存元氣如保留碩果,勿耗盡精力","保存真愛如保留碩果,勿全部失去","保存本金如保留碩果,勿全部虧光","保存實力如保留碩果,勿全部套牢","保存信用如保留碩果,勿全部刷爆","保存證據如保留碩果,勿全盤皆輸","保存資產如保留碩果,勿全部賠光"]},"24-1":{"name":"初九","text":"不遠復,无祗悔,元吉","level":"L1","kw":["不遠復","及時","元吉","回頭"],"i":["及時改正錯誤,事業大獲成功","及時就醫治療,身體完全康復","及時道歉和好,感情更加美滿","及時停損認錯,財務轉危為安","及時停損出場,避免更大虧損","及時分手止損,避免更大損失","及時和解認錯,避免敗訴賠償","及時取消交易,避免買到爛屋"]},"24-2":{"name":"六二","text":"休復,吉","level":"L2","kw":["休復","美好","吉","善行"],"i":["效法善良榜樣,事業蒸蒸日上","效法養生榜樣,身體日益健康","效法美好榜樣,感情日益甜蜜","效法成功榜樣,財富日益增長","效法大師榜樣,獲利日益豐厚","效法理性榜樣,婚姻日益健康","效法成功案例,訴訟日益有利","效法成功案例,購屋日益順利"]},"24-3":{"name":"六三","text":"頻復,厲,无咎","level":"L4","kw":["頻復","反覆","厲","无咎"],"i":["反覆犯錯雖危險,但能改正無大礙","病情反覆雖危險,但能治癒無大礙","爭執反覆雖危險,但能和好無大礙","虧損反覆雖危險,但能回本無大礙","套牢反覆雖危險,但能解套無大礙","分手反覆雖麻煩,但能解決無大礙","訴訟反覆雖危險,但能勝訴無大礙","交易反覆雖危險,但能成交無大礙"]},"24-4":{"name":"六四","text":"中行獨復","level":"L3","kw":["中行","獨復","獨立","正道"],"i":["不隨波逐流,獨立改正走正道","不隨便吃藥,獨立判斷找良醫","不隨便交往,獨立思考找真愛","不隨便投資,獨立判斷穩健財","不隨便跟單,獨立研究穩健利","不隨便發展關係,獨立判斷理性婚姻","不隨便妥協,獨立判斷堅持正義","不隨便購買,獨立判斷找好房"]},"24-5":{"name":"六五","text":"敦復,无悔","level":"L2","kw":["敦復","厚道","无悔","誠懇"],"i":["誠懇改正錯誤,深得人心無悔","誠懇配合治療,完全康復無悔","誠懇道歉認錯,對方原諒無悔","誠懇承認虧損,客戶諒解無悔","誠懇認賠停損,及時止血無悔","誠懇溝通分手,長輩同意無悔","誠懇認錯和解,雙方滿意無悔","誠懇溝通取消,屋主諒解無悔"]},"24-6":{"name":"上六","text":"迷復,凶,有災眚,用行師,終有大敗,以其國君,凶,至于十年不克征","level":"L9","kw":["迷復","凶","大敗","十年"],"i":["執迷不悟不肯改,事業慘敗長期難翻身","執迷不悟不肯治,病情惡化長期難康復","執迷不悟不肯認錯,感情破裂長期難復合","執迷不悟不肯止損,破產慘重長期難翻身","執迷不悟不肯停損,血本無歸長期難回本","執迷不悟不肯節制,陷入困境長期難還清","執迷不悟不肯和解,敗訴慘重長期難翻身","執迷不悟不肯認賠,套牢慘重長期難脫手"]},"25-1":{"name":"初九","text":"無妄,往吉","level":"L2","kw":["無妄","真誠","往吉","順天"],"i":["真誠行事順應天道,前進必獲成功","真誠養生順應自然,身體自然健康","真誠相待順應真心,感情自然美滿","真誠經營順應正道,財富自然增長","真誠投資順應市場,獲利自然豐厚","真誠婚姻順應需求,婚姻自然滿意","真誠訴訟順應正義,勝訴自然到來","真誠購屋順應需求,房產自然滿意"]},"25-2":{"name":"六二","text":"不耕獲,不菑畬,則利有攸往","level":"L2","kw":["不耕獲","意外收穫","利","天賜"],"i":["不求回報真誠付出,意外遇到成功","不求速效自然養生,意外遇到健康","不求回報真心付出,意外遇到真愛","不求暴利誠信經營,意外遇到財富","不求暴利長期持有,意外遇到厚利","不求條件低人品為先,意外遇到良緣","不求勝訴只求正義,意外遇到勝訴","不求便宜品質為先,意外遇到好房"]},"25-3":{"name":"六三","text":"無妄之災,或繫之牛,行人之得,邑人之災","level":"L7","kw":["無妄災","意外","災","無辜"],"i":["無辜遭受意外災難,他人得利自己受害","無辜染病或受傷,意外的健康危機","無辜被第三者破壞,意外的感情災難","無辜遭受財務損失,意外的破財之災","無辜遭遇市場崩盤,意外的投資虧損","無辜遇到問題婚姻,意外的婚姻糾紛","無辜被捲入訴訟,意外的法律麻煩","無辜買到問題房屋,意外的購屋災難"]},"25-4":{"name":"九四","text":"可貞,无咎","level":"L3","kw":["可貞","堅守","无咎","正道"],"i":["堅守正道不妄為,可保平安無過失","堅守養生不亂吃藥,可保健康無病痛","堅守忠誠不亂來,可保感情無波折","堅守正業不投機,可保財富無虧損","堅守原則不亂投,可保本金無虧損","堅守條件不亂發展關係,可保護自己無赤字","堅守正義不妄訴,可保清白無敗訴","堅守標準不亂買,可保資產無套牢"]},"25-5":{"name":"九五","text":"無妄之疾,勿藥有喜","level":"L2","kw":["無妄疾","勿藥","有喜","自癒"],"i":["意外的小挫折,不必刻意處理自然好轉","小病小痛,不必吃藥自然痊癒","小爭執,不必刻意道歉自然和好","小虧損,不必刻意彌補自然回本","小套牢,不必刻意操作自然解套","小缺點,不必刻意分手自然接受","小糾紛,不必刻意訴訟自然和解","小問題,不必刻意修繕自然沒事"]},"25-6":{"name":"上九","text":"無妄,行有眚,无攸利","level":"L6","kw":["無妄","行眚","无攸利","妄動"],"i":["此時妄動必有災禍,什麼都不宜做","此時亂動必有傷害,靜養為上","此時妄動必有爭執,保持現狀為佳","此時妄動必有損失,守成為上","此時妄動必有虧損,空手為上","此時妄動必有損失,不發展關係為上","此時妄動必有敗訴,不訴為上","此時妄動必有套牢,不買為上"]},"26-1":{"name":"初九","text":"有厲,利己","level":"L4","kw":["有厲","危險","利己","停止"],"i":["前有危險,暫停前進最有利","病情危險,暫停活動靜養為宜","感情危險,暫停進展冷靜為宜","財務危險,暫停投資保守為宜","市場危險,暫停進場觀望為宜","婚姻有危機,暫停發展關係謹慎為宜","訴訟危險,暫停提告準備為宜","購屋危險,暫停交易觀望為宜"]},"26-2":{"name":"九二","text":"輿說輹","level":"L4","kw":["輿說輹","車壞","停止","修整"],"i":["進展受阻需修整,暫停調整為宜","身體不適需休養,暫停活動為宜","感情受阻需溝通,暫停進展為宜","財務受阻需檢討,暫停擴張為宜","投資受阻需調整,暫停加碼為宜","婚姻受阻需節制,暫停發展關係為宜","訴訟受阻需調整,暫停進攻為宜","購屋受阻需重評,暫停交易為宜"]},"26-3":{"name":"九三","text":"良馬逐,利艱貞,曰閑輿衛,利有攸往","level":"L2","kw":["良馬","逐","艱貞","利往"],"i":["有良好條件可前進,堅持正道必成功","有良好體質可治療,堅持養生必康復","有良好對象可追求,堅持真誠必成功","有良好機會可投資,堅持正道必獲利","有良好標的可進場,堅持原則必獲利","有良好婚姻可發展關係,堅持人品必滿意","有良好證據可提告,堅持正義必勝訴","有良好房產可購買,堅持標準必滿意"]},"26-4":{"name":"六四","text":"童牛之牿,元吉","level":"L1","kw":["童牛","牿","預防","元吉"],"i":["及早培養人才防患未然,大獲成功","及早預防疾病養生保健,身體健康","及早建立規則防範問題,感情美滿","及早規劃理財防範風險,財富增長","及早設定停損防範虧損,獲利豐厚","及早建立原則防範過度,關係健康","及早準備證據防範敗訴,順利勝訴","及早評估風險防範套牢,購屋滿意"]},"26-5":{"name":"六五","text":"豶豕之牙,吉","level":"L2","kw":["豶豕","牙","化解","吉"],"i":["化解危險於無形,事業平安順利","化解病痛於初期,身體健康無虞","化解爭執於萌芽,感情和諧美滿","化解危機於開始,財務穩健增長","化解風險於初期,投資穩健獲利","化解糾紛於開始,婚姻順利滿意","化解紛爭於調解,訴訟和平收場","化解問題於驗屋,購屋順利滿意"]},"26-6":{"name":"上九","text":"何天之衢,亨","level":"L1","kw":["何天衢","亨","通達","成功"],"i":["達到最高成就,事業通達無阻","達到最佳狀態,身體健康強壯","達到最佳關係,感情美滿幸福","達到財富自由,財務通達無憂","達到投資高峰,獲利豐厚通達","達到婚姻智慧,婚姻滿意通達","達到完全勝訴,正義得以伸張","達到理想居所,房產滿意通達"]},"27-1":{"name":"初九","text":"舍爾靈龜,觀我朵頤,凶","level":"L8","kw":["舍靈龜","朵頤","貪婪","凶"],"i":["放棄長遠利益追求眼前小利,災難將至","放棄養生貪吃美食,健康受損嚴重","放棄真愛追求物質,感情破裂痛苦","放棄正業追求投機,財務崩潰破產","放棄價值追求暴利,投資虧損慘重","放棄理性追求享樂,婚姻失控困境","放棄正義追求勝訴,反而敗訴慘重","放棄品質追求便宜,買到爛屋後悔"]},"27-2":{"name":"六二","text":"顛頤,拂經,于丘頤,征凶","level":"L7","kw":["顛頤","拂經","違常","凶"],"i":["顛倒是非違反常理,前進必遭失敗","違反醫囑亂吃亂補,病情惡化嚴重","顛倒關係違反倫理,感情混亂痛苦","顛倒手段違反商道,財務崩潰破產","顛倒邏輯違反規律,投資慘敗虧損","顛倒需求違反理性,婚姻混亂崩潰","顛倒是非違反法律,訴訟敗訴慘重","顛倒標準違反常理,購屋失敗套牢"]},"27-3":{"name":"六三","text":"拂頤,貞凶,十年勿用,无攸利","level":"L9","kw":["拂頤","違養","十年","无利"],"i":["違反正道謀生,長期無法翻身","違反養生之道,長期病痛纏身","違反相處之道,長期感情不順","違反經營之道,長期財務困難","違反投資之道,長期虧損套牢","違反婚姻之道,長期難以自拔","違反法律之道,長期訴訟纏身","違反購屋之道,長期套牢難脫"]},"27-4":{"name":"六四","text":"顛頤,吉,虎視眈眈,其欲逐逐,无咎","level":"L2","kw":["顛頤","虎視","吉","強勢"],"i":["以強勢手段養活團隊,雖非常規但成功","以特殊方法治療疾病,雖非常規但有效","以主動方式追求對象,雖非常規但成功","以創新方法賺取財富,雖非常規但獲利","以積極策略進場投資,雖非常規但賺錢","以特殊管道發展關係婚姻,雖非常規但滿意","以強硬態度進行訴訟,雖非常規但勝訴","以特殊方式購買房產,雖非常規但成功"]},"27-5":{"name":"六五","text":"拂經,居貞吉,不可涉大川","level":"L4","kw":["拂經","居貞","守成","不涉"],"i":["違反常規但守住本業吉,不宜冒險擴張","特殊療法但持續保養吉,不宜激進治療","非典型關係但維持現狀吉,不宜急於改變","非主流收入但守住本金吉,不宜大額投資","非典型標的但持有不動吉,不宜大額加碼","非傳統緣分但適度發展可行，不宜過度投入","非典型策略但維持現狀吉,不宜擴大訴訟","非典型房產但維持現狀吉,不宜再行投資"]},"27-6":{"name":"上九","text":"由頤,厲,吉,利涉大川","level":"L2","kw":["由頤","厲","吉利","養人"],"i":["承擔養活眾人責任雖艱難但成功,適合大展拳腳","承擔照顧家人責任雖辛苦但值得,適合全力以赴","承擔養家責任雖壓力大但甜蜜,適合結婚生子","承擔企業責任雖風險高但獲利,適合擴大經營","承擔基金經理責任雖壓力大但賺錢,適合大額操作","承擔家庭責任雖壓力大但必要,適合重大決定","承擔集體訴訟責任雖艱難但正義,適合提起訴訟","承擔家族居住責任雖負擔重但必要,適合購買大屋"]},"28-1":{"name":"初六","text":"藉用白茅,无咎","level":"L3","kw":["藉白茅","謹慎","无咎","過慎"],"i":["過度謹慎雖稍顯保守但無害","過度小心雖稍顯緊張但無礙","過度謹慎雖稍顯冷淡但無害","過度保守雖獲利少但保本","過度謹慎雖賺得少但不虧","過度節儉雖發展關係得少但無債","過度謹慎雖進展慢但穩健","過度挑剔雖買得慢但品質好"]},"28-2":{"name":"九二","text":"枯楊生稊,老夫得其女妻,无不利","level":"L2","kw":["枯楊","生稊","復甦","无不利"],"i":["事業起死回生,老樹開花重獲生機","身體康復回春,枯木逢春重獲健康","感情重燃熱火,老夫少妻重獲甜蜜","財務起死回生,枯木逢春重獲財富","投資起死回生,套牢解套重獲利潤","婚姻恢復正常,心情好轉重獲自由","訴訟起死回生,敗部復活重獲勝訴","房產起死回生,脫手成功重獲資金"]},"28-3":{"name":"九三","text":"棟橈,凶","level":"L9","kw":["棟橈","支柱","崩潰","凶"],"i":["核心支柱崩潰,事業面臨倒閉","重要器官衰竭,生命面臨危險","感情支柱崩潰,關係面臨破裂","財務支柱崩潰,企業面臨破產","投資支柱崩潰,資金面臨歸零","婚姻支柱崩潰,信任崩潰","訴訟支柱崩潰,案件面臨慘敗","房產支柱崩潰,建築面臨倒塌"]},"28-4":{"name":"九四","text":"棟隆,吉,有它,吝","level":"L3","kw":["棟隆","興旺","吉","有它吝"],"i":["事業興旺發達,但若有其他念頭則不妙","身體健康強壯,但若不繼續保養則不佳","感情甜蜜美滿,但若出現第三者則糟糕","財務興旺發達,但若貪心投機則虧損","投資興旺獲利,但若貪心加碼則套牢","婚姻健康適度,但若揮霍無度則崩潰","訴訟順利進行,但若態度傲慢則翻盤","房產增值滿意,但若投機炒房則套牢"]},"28-5":{"name":"九五","text":"枯楊生華,老婦得其士夫,无咎无譽","level":"L4","kw":["枯楊","生華","老婦","无咎譽"],"i":["事業雖有起色但難持久,虽無過但無功","身體雖有好轉但難根治,雖無惡化但無痊癒","感情雖有復合但難長久,雖無爭執但無激情","財務雖有好轉但難富裕,雖無虧損但無大獲","投資雖有獲利但難持久,雖無虧損但無厚利","婚姻雖有節制但難滿意,雖無過度但無快樂","訴訟雖無敗訴但難勝訴,雖無損失但無賠償","房產雖無貶值但難增值,雖無套牢但無獲利"]},"28-6":{"name":"上六","text":"過涉滅頂,凶,无咎","level":"L8","kw":["過涉","滅頂","凶","盡力"],"i":["過度冒險雖失敗但已盡力,雖凶但無遺憾","過度勞累雖病倒但已盡力,雖凶但無愧疚","過度付出雖分手但已盡力,雖凶但無後悔","過度投資雖破產但已盡力,雖凶但無遺憾","過度加碼雖慘賠但已盡力,雖凶但無後悔","過度投入雖崩潰但已享受,雖凶但無遺憾","過度堅持雖慘敗但已盡力,雖凶但無愧疚","過度投資雖套牢但已盡力,雖凶但無後悔"]},"29-1":{"name":"初六","text":"習坎,入于坎窞,凶","level":"L9","kw":["習坎","坎窞","深陷","凶"],"i":["陷入困境越陷越深,極度危險","病情惡化越來越重,極度危險","感情泥沼越陷越深,極度痛苦","財務黑洞越陷越深,破產在即","投資套牢越陷越深,血本無歸","困境黑洞越陷越深,崩潰在即","訴訟泥沼越陷越深,敗訴慘重","房貸黑洞越陷越深,法拍在即"]},"29-2":{"name":"九二","text":"坎有險,求小得","level":"L5","kw":["坎險","求小得","困境","小成"],"i":["困境中只能求小成就,難有大作為","病情中只能求小康復,難以根治","危機中只能求小和解,難以如初","困境中只能求小獲利,難以致富","套牢中只能求小解套,難有大獲","困境中只能發展關係條件差的對象,難覓良緣","困境中只能求小勝訴,難以全勝","困境中只能買小房子,難買大房"]},"29-3":{"name":"六三","text":"來之坎坎,險且枕,入于坎窞,勿用","level":"L9","kw":["坎坎","險枕","勿用","絕境"],"i":["前後都是險境,什麼都不要做","病情危重,什麼都不要嘗試","感情絕境,什麼都不要做","財務絕境,什麼都不要投資","投資絕境,什麼都不要操作","處境艱難,暫不宜發展關係","訴訟絕境,什麼都不要做","房產絕境,什麼都不要動"]},"29-4":{"name":"六四","text":"樽酒,簋貳,用缶,納約自牖,終无咎","level":"L3","kw":["樽酒","簋貳","簡約","終无咎"],"i":["困境中以簡約誠意相待,最終化險為夷","病情中以簡單方法治療,最終康復平安","危機中以真誠態度溝通,最終和好如初","困境中以節儉方式經營,最終轉虧為盈","套牢中以簡單策略應對,最終解套獲利","困境中以簡樸方式經營婚姻,最終關係健康","困境中以誠意態度和解,最終和平收場","困境中以簡約方式購屋,最終滿意無悔"]},"29-5":{"name":"九五","text":"坎不盈,祇既平,无咎","level":"L3","kw":["坎不盈","既平","无咎","脫困"],"i":["困境未滿即將脫困,度過危機平安無事","病情未滿即將康復,度過危機身體健康","危機未滿即將和好,度過危機感情如初","困境未滿即將轉機,度過危機財務健康","套牢未滿即將解套,度過危機獲利在望","困境即將過去,度過危機重獲自由","困境未滿即將和解,度過危機平安收場","困境未滿即將脫手,度過危機資金回籠"]},"29-6":{"name":"上六","text":"繫用徽纆,寘于叢棘,三歲不得,凶","level":"L9","kw":["繫徽纆","叢棘","三歲","凶"],"i":["被困住長期無法脫身,極度凶險","被疾病困住長期無法痊癒,極度危險","被感情困住長期無法解脫,極度痛苦","被債務困住長期無法翻身,破產在即","被套牢困住長期無法解套,血本無歸","被困境困住長期無法還清,崩潰在即","被訴訟困住長期無法脫身,敗訴慘重","被房貸困住長期無法脫身,法拍在即"]},"30-1":{"name":"初九","text":"履錯然,敬之,无咎","level":"L3","kw":["履錯","敬之","謹慎","无咎"],"i":["初期雖有錯誤但謹慎對待,可保平安","初期雖有不適但謹慎治療,可保健康","初期雖有爭執但謹慎溝通,可保和諧","初期雖有虧損但謹慎理財,可保本金","初期雖有套牢但謹慎操作,可保解套","初期雖有過度但謹慎節制,可保護自己","初期雖有不利但謹慎應對,可保平安","初期雖有問題但謹慎檢查,可保滿意"]},"30-2":{"name":"六二","text":"黃離,元吉","level":"L1","kw":["黃離","中道","元吉","完美"],"i":["處於中庸之道,事業大獲全勝","保持中庸養生,身體極度健康","保持中庸相處,感情極度美滿","保持中庸理財,財富極度豐厚","保持中庸投資,獲利極度豐厚","保持中庸婚姻,關係極度穩定","保持中庸態度,訴訟極度順利","保持中庸標準,房產極度滿意"]},"30-3":{"name":"九三","text":"日昃之離,不鼓缶而歌,則大耋之嗟,凶","level":"L7","kw":["日昃","大耋","衰老","凶"],"i":["事業走下坡不知享樂,只能哀嘆衰老","身體走下坡不知保養,只能哀嘆病痛","感情走下坡不知珍惜,只能哀嘆孤獨","財富走下坡不知享受,只能哀嘆貧困","獲利走下坡不知止盈,只能哀嘆虧損","婚姻走下坡不知享受,只能哀嘆貧困","訴訟走下坡不知和解,只能哀嘆敗訴","房價走下坡不知脫手,只能哀嘆套牢"]},"30-4":{"name":"九四","text":"突如其來如,焚如,死如,棄如","level":"L9","kw":["突如","焚如","死如","棄如"],"i":["突然崩潰如火燒,如死亡,如被拋棄","突然惡化如火燒,生命垂危瀕死","突然破裂如火燒,如死別,如被拋棄","突然崩盤如火燒,破產如死,如被拋棄","突然暴跌如火燒,血本無歸如死","突然崩潰如火燒,信任全失如死","突然敗訴如火燒,傾家蕩產如死","突然倒塌如火燒,房財兩失如死"]},"30-5":{"name":"六五","text":"出涕沱若,戚嗟若,吉","level":"L3","kw":["出涕","戚嗟","悲傷","吉"],"i":["悲傷哭泣後反省改進,最終成功","悲傷痛苦後改變習慣,最終康復","悲傷哭泣後真誠溝通,最終和好","悲傷懊悔後改變策略,最終獲利","悲傷痛苦後調整策略,最終賺錢","悲傷後悔後改變習慣,最終健康","悲傷痛苦後改變策略,最終勝訴","悲傷後悔後改變標準,最終滿意"]},"30-6":{"name":"上九","text":"王用出征,有嘉折首,獲匪其醜,无咎","level":"L2","kw":["王出征","折首","獲","无咎"],"i":["主動出擊消滅禍首,大獲全勝無過失","主動治療根除病因,完全康復無後遺症","主動出擊解決問題,感情美滿無遺憾","主動出擊把握機會,財富豐厚無虧損","主動出擊精準投資,獲利豐厚無虧損","主動出擊精明婚姻,找到理想伴侶無遺憾","主動出擊精準打擊,完全勝訴無損失","主動出擊精準購屋,房產滿意無遺憾"]},"31-1":{"name":"初六","text":"咸其拇","level":"L4","kw":["咸拇","初動","微感","開始"],"i":["剛開始有感應,尚未確定是否行動","剛開始有不適,尚未確定是否就醫","剛開始有好感,尚未確定是否追求","剛開始有機會,尚未確定是否投資","剛開始有興趣,尚未確定是否進場","剛開始有想法,尚未確定是否發展關係","剛開始有想法,尚未確定是否提告","剛開始有興趣,尚未確定是否購買"]},"31-2":{"name":"六二","text":"咸其腓,凶,居吉","level":"L5","kw":["咸腓","輕率","居吉","不動"],"i":["輕率行動會失敗,停留不動反而好","輕率治療會惡化,靜養不動反而好","輕率追求會失敗,等待不動反而好","輕率投資會虧損,持幣不動反而好","輕率進場會套牢,觀望不動反而好","輕率發展關係會後悔,忍住不發展關係反而好","輕率提告會敗訴,暫緩不動反而好","輕率購買會套牢,等待不動反而好"]},"31-3":{"name":"九三","text":"咸其股,執其隨,往吝","level":"L6","kw":["咸股","執隨","往吝","被動"],"i":["被動跟隨他人,前進會很難堪","被動聽從他人,治療會不理想","被動跟隨對方,感情會不平等","被動跟隨他人,投資會很吃虧","被動跟單他人,操作會很虧損","被動聽從甜言蜜語,婚姻會很後悔","被動聽從律師,訴訟會不理想","被動聽從仲介,購屋會不滿意"]},"31-4":{"name":"九四","text":"貞吉,悔亡,憧憧往來,朋從爾思","level":"L2","kw":["貞吉","悔亡","憧憧","朋從"],"i":["堅守正道悔恨消失,真誠待人朋友追隨","堅守養生悔恨消失,真誠求醫醫生盡心","堅守真愛悔恨消失,真誠相待對方追隨","堅守正道悔恨消失,真誠經營客戶信賴","堅守原則悔恨消失,真誠研究獲利豐厚","堅守理性悔恨消失,真誠婚姻長輩良緣","堅守正義悔恨消失,真誠陳述法官信任","堅守標準悔恨消失,真誠議價屋主割愛"]},"31-5":{"name":"九五","text":"咸其脢,无悔","level":"L4","kw":["咸脢","背部","无悔","淺感"],"i":["感應不深難有大成,但無遺憾","感覺不強難以根治,但無惡化","感情不深難以長久,但無傷害","感覺不強難以致富,但無虧損","感覺不強難以大獲,但無虧損","感覺不強難以滿意,但無遺憾","感覺不強難以勝訴,但無敗訴","感覺不強難以滿意,但無套牢"]},"31-6":{"name":"上六","text":"咸其輔頰舌","level":"L6","kw":["咸輔","頰舌","空談","無實"],"i":["只有空談沒有實際行動,難有成就","只有想法沒有實際行動,難以康復","只有甜言沒有實際行動,難以長久","只有空談沒有實際行動,難以致富","只有想法沒有實際行動,難以獲利","只有想法沒有實際行動,難以滿足","只有空談沒有實際證據,難以勝訴","只有想法沒有實際行動,難以購得"]},"32-1":{"name":"初六","text":"浚恆,貞凶,无攸利","level":"L8","kw":["浚恆","急躁","貞凶","无利"],"i":["剛開始就急於求成,什麼都不會順利","剛開始就急於見效,反而會更糟糕","剛開始就急於結婚,感情會很失敗","剛開始就急於致富,財務會很慘重","剛開始就急於獲利,投資會很虧損","剛開始就急於發展關係,婚姻會很後悔","剛開始就急於提告,訴訟會很慘敗","剛開始就急於購買,購屋會很套牢"]},"32-2":{"name":"九二","text":"悔亡","level":"L3","kw":["悔亡","恰當","持久","滿意"],"i":["恰當持久地工作,悔恨自然消失","恰當持久地養生,身體自然健康","恰當持久地相處,感情自然美滿","恰當持久地經營,財富自然增長","恰當持久地持有,獲利自然豐厚","恰當持久地使用,婚姻自然滿意","恰當持久地準備,訴訟自然順利","恰當持久地居住,房產自然滿意"]},"32-3":{"name":"九三","text":"不恆其德,或承之羞,貞吝","level":"L6","kw":["不恆","不堅持","羞","吝"],"i":["不能持之以恆,會受到羞辱難堪","不能持續養生,會受到病痛折磨","不能持續真誠,會受到對方責備","不能持續經營,會受到客戶唾棄","不能持續持有,會受到虧損打擊","不能持續節制,會受到困境困擾","不能持續準備,會受到敗訴打擊","不能持續保養,會受到貶值打擊"]},"32-4":{"name":"九四","text":"田无禽","level":"L6","kw":["田无禽","無獲","徒勞","失敗"],"i":["長期努力卻一無所獲,徒勞無功","長期治療卻不見效果,白費力氣","長期追求卻得不到人,白費心思","長期經營卻沒有收入,白費時間","長期持有卻沒有獲利,白費資金","長期等待卻找不到對象,白費時間","長期訴訟卻得不到結果,白費金錢","長期找房卻買不到房,白費時間"]},"32-5":{"name":"六五","text":"恆其德,貞,婦人吉,夫子凶","level":"L4","kw":["恆其德","婦吉","夫凶","守舊"],"i":["堅守舊法,執行者吉但領導者凶","堅守舊法,養生者吉但創新者不宜","堅守舊法,順從者吉但主導者不宜","堅守舊法,保守者吉但創業者不宜","堅守舊法,定存者吉但投資者不宜","堅守舊法,節儉者吉但享受者不宜","堅守舊法,守規者吉但創新者不宜","堅守舊法,租屋者吉但購屋者不宜"]},"32-6":{"name":"上六","text":"振恆,凶","level":"L8","kw":["振恆","過度","凶","不穩"],"i":["過度求變動盪不安,極度危險","過度治療反覆不定,極度危險","過度求變反覆不定,感情破裂","過度求變動盪不安,財務崩潰","過度操作反覆不定,虧損慘重","過度投入反覆不定,難以自拔","過度變更反覆不定,訴訟慘敗","過度買賣反覆不定,資產耗盡"]},"33-1":{"name":"初六","text":"遯尾，厲，勿用有攸往","level":"L7","kw":["遯尾","危險","莫動"],"i":["處於不利地位，不宜變動，宜守不宜進","腿部或末梢循環不佳，宜靜養","感情受阻，宜退後觀察，勿急於追求","財運不佳，暫不宜投資或擴張","不宜進場，以免被套牢","不宜發展關係，現在不是好時機","形勢不利，暫避鋒芒為上","房產位置偏僻或基礎不穩，不宜購買"]},"33-2":{"name":"六二","text":"執之用黃牛之革，莫之勝說","level":"L2","kw":["黃牛革","堅定","守正"],"i":["意志堅定，能克服誘惑或困難，最終獲利","注意皮膚或脾胃保養，堅持健康計畫","感情關係穩固，對方心意堅定","財運平穩，適合定期定額或穩健理財","適合長期持有，不被市場波動干擾","遇到可靠、真心實意的好對象","立場堅定且有理，終能勝訴","產權穩固，交易雖然耗時但結果吉祥"]},"33-3":{"name":"九三","text":"係遯，有疾厲，畜臣妾吉","level":"L4","kw":["係遯","牽絆","小吉"],"i":["被瑣事或舊勢力牽絆，難以脫身，宜從小處著手","注意慢性病反覆，或因壓力導致的小疾","感情有牽絆，難以果斷抉擇，宜耐心溝通","小財可得，但大財受阻","不宜大額操作，適合小量試單","小事可成，大事不宜","糾紛纏身難以結案，適合尋求和解","適合處理小坪數或租賃事務"]},"33-4":{"name":"九四","text":"好遯，君子吉，小人否","level":"L2","kw":["好遯","果斷","轉身"],"i":["能在關鍵時刻優雅轉身，避開風險，吉","心態豁達，有助於身心康復","能理智處理感情問題，不再糾結","見好就收，能保住財富獲利","在高點獲利了結，避免回檔風險","遇到條件優秀的對象，滿意","理智放棄無效訴訟，反而大吉","賣出舊屋或換得更理想的環境"]},"33-5":{"name":"九五","text":"嘉遯，貞吉","level":"L1","kw":["嘉遯","讚譽","大吉"],"i":["處置得當受到眾人稱讚，前途光明大吉","身心狀態處於最佳平衡點","感情關係令人稱羨，未來圓滿","財運極佳，名利雙收，大吉","眼光精確，獲得豐厚回報","遇到令人讚不絕口的理想對象","遇到尊榮級的勝訴或公正對待","買到旺宅，家運興隆"]},"33-6":{"name":"上九","text":"肥遯，无不利","level":"L1","kw":["肥遯","優游","通達"],"i":["毫無牽絆，自由自在，發展無往不利","精力充沛，如飛鳥在天，極其健康","感情關係輕鬆自在，充滿幸福感","財富自由，衣食無憂，無往不利","投資獲利豐厚，資金調度自由","自由發展關係，找到理想伴侶","徹底脫離糾紛，勝訴且遇到自由","擁有多處房產，居住自由通達"]},"34-1":{"name":"初九","text":"壯于趾，征凶，有孚","level":"L7","kw":["壯于趾","躁進","征凶","根基"],"i":["能力尚未成熟就急於表現，容易遭受挫折","足部受傷或循環不良，不宜過度運動","單方面熱情過度，對方感到壓力，進展不順","資金根基不穩，貿然投資會虧損","市場剛起步但不穩，進場過早會被套牢","衝動決定，發展關係了不實用的關係","證據不足就提告，起步就輸","地基或基礎建設有問題，不宜購買"]},"34-2":{"name":"九二","text":"貞吉","level":"L3","kw":["貞吉","中道","穩健","得位"],"i":["堅守崗位，穩健行事，事業順利","保持規律作息，身體健康穩定","感情穩定發展，堅持初心有好結果","正財收入穩定，不求暴利反而長久","選擇穩健型標的，長期持有獲利","找到穩定可靠的關係，值得珍惜","堅持正義，站得住腳，最終勝訴","選擇格局方正的房子，居住平安"]},"34-3":{"name":"九三","text":"小人用壯，君子用罔，貞厲，羝羊觸藩，羸其角","level":"L8","kw":["用壯","觸藩","困境","蠻力"],"i":["恃才傲物或蠻幹，反而陷入進退兩難的困境","過度鍛鍊導致受傷，或硬撐導致病情惡化","太過強勢導致爭吵，關係陷入僵局","孤注一擲投機，導致資金卡死","硬碰硬操作，追高殺低，虧損慘重","硬要發展關係不適合的婚姻，造成遺憾","態度強硬不肯和解，導致案情膠著","執意買入有爭議的房產，導致產權糾紛"]},"34-4":{"name":"九四","text":"貞吉，悔亡，藩決不羸，壯于大輿之輹","level":"L2","kw":["藩決","突破","大輿","順利"],"i":["障礙消除，能力強大且有資源支持，大展宏圖","頑疾治癒，身體恢復強壯，行動自如","突破障礙，雙方關係更進一步，阻力消失","財務障礙解除，財運大開，收入豐厚","突破壓力區，獲利豐厚，趨勢向上","遇到夢寐以求的婚姻，進展順利","案情突破僵局，遇到有利證據，勝訴","交通便利，升值潛力大，適合購入"]},"34-5":{"name":"六五","text":"喪羊于易，无悔","level":"L4","kw":["喪羊","柔和","无悔","退讓"],"i":["收斂強勢作風，以柔克剛，無悔","放鬆心情，不再緊繃，身體自然好轉","不再固執己見，互相退讓，感情回溫","不強求暴利，順其自然，財務平安","不強行操作，適時休息，避免虧損","不強求出身，隨性婚姻，反而滿意","放棄強硬對抗，尋求和解，無後患","不強求精華地段，選擇舒適區，居住滿意"]},"34-6":{"name":"上六","text":"羝羊觸藩，不能退，不能遂，无攸利，艱則吉","level":"L6","kw":["觸藩","進退兩難","艱","堅持"],"i":["進退維谷，卡在中間，需忍耐艱苦才能度過","病情膠著，好轉緩慢，需長期調養","關係卡住，分不掉也合不來，極度煎熬","資金被套牢，無法動用，需苦撐","被套在山頂，割肉痛不割也痛，進退兩難","發展關係了昂貴卻無用的關係，分手無門","訴訟陷入泥沼，長期拖延，消耗極大","房產滯銷，賣不掉也租不出，資金壓力大"]},"35-1":{"name":"初六","text":"晉如，摧如，貞吉。罔孚，裕无咎","level":"L4","kw":["晉如","摧如","挫折","寬容"],"i":["剛升遷就遇挫折，沒人信任，需寬容待之","治療初期效果不明顯，需耐心堅持","追求初期受挫，對方不信任，需保持寬裕心態","初期收益不如預期，需放長線釣大魚","進場後小幅回檔，勿驚慌，長期看好","發展關係不到想要的，別太在意，下次還有機會","初期形勢不利，需保持冷靜，堅守正道","看房受挫，但保持耐心終會找到好房"]},"35-2":{"name":"六二","text":"晉如，愁如，貞吉。受茲介福，于其王母","level":"L3","kw":["愁如","介福","貴人","轉機"],"i":["雖有憂愁但堅守正道，終獲女性長輩或貴人提拔","擔心病情，但會遇到良醫，吉","為情所困，但會有長輩牽線，終成眷屬","財務有壓力，但會遇到資助，轉危為安","市場波動令人擔憂，但長期持有有厚福","猶豫不決，但最終遇到找到理想伴侶的婚姻","憂心忡忡，但會遇到有力人士調解","擔心買不到，但最終會遇到家中資助購屋"]},"35-3":{"name":"六三","text":"眾允，悔亡","level":"L2","kw":["眾允","認同","悔亡","團隊"],"i":["遇到眾人信任與支持，消除悔恨，事業順利","多方會診意見一致，治療方向正確","這段關係遇到親友大家認可，無悔","集資順利，眾人看好，財運亨通","跟隨市場主流趨勢，獲利無悔","大家都推薦的婚姻，發展關係了不會後悔","輿論支持，證人有利，形勢大好","社區管理良好，住戶素質高，居住滿意"]},"35-4":{"name":"九四","text":"晉如鼫鼠，貞厲","level":"L8","kw":["鼫鼠","投機","貪婪","危險"],"i":["位高權重但心術不正，如碩鼠般貪婪，危險","隱疾潛伏，如鼠在穴，需徹底檢查","動機不純，貪圖對方財勢，感情充滿危機","靠投機取巧獲利，終將面臨法律風險","短線投機過度，面臨被套殺的危險","貪圖小利遇到不正當關係或虛情假意，惹禍上身","因貪婪而興訟，立場不正，極度危險","產權不清或佔用他人土地，後患無窮"]},"35-5":{"name":"六五","text":"悔亡，失得勿恤，往吉，无不利","level":"L1","kw":["失得勿恤","大度","往吉","豁達"],"i":["不計較一時得失，眼光長遠，前途大吉","放寬心胸，不計較小病痛，身體自然康復","不計較誰付出多，大度相愛，幸福美滿","不在意短期波動，長線佈局，獲利豐厚","忽視短期漲跌，堅持價值投資，大賺","不計較條件，遇到真正喜歡的關係，值得","不計較小節，專注大局，勝訴","不計較房價一時起伏，買到好地段，增值"]},"35-6":{"name":"上九","text":"晉其角，維用伐邑，厲吉无咎，貞吝","level":"L5","kw":["晉其角","伐邑","極端","強硬"],"i":["進攻到極點，只能用於內部整頓，對外擴張不利","用藥過猛，雖治病但傷身，需謹慎","態度過於強硬，雖爭贏了道理但傷了感情","強行收回債務，雖有收穫但得罪人","強弩之末，不宜再追高，小心反轉","過度斤斤計較，雖發展關係條件低但人品堪憂","強行提告，雖勝訴但代價慘重","強行拆遷或改造，雖成功但引發民怨"]},"36-1":{"name":"初九","text":"明夷于飛，垂其翼。君子于行，三日不食，有攸往，主人有言","level":"L6","kw":["垂翼","逃亡","不食","讒言"],"i":["環境險惡，才華受壓制，宜低調離開，忍受飢寒","身體虛弱，飲食不振，需緊急調養","感情受阻，被迫分離，對方家長有閒言閒語","生計困難，甚至三日不食，需忍耐度日","市場崩盤初期，趕緊停損離場，雖痛但保命","條件極度緊缺，只能維持基本生存","被迫遠走他鄉避禍，不宜興訟","被迫搬遷，居住環境惡劣"]},"36-2":{"name":"六二","text":"明夷，夷于左股，用拯馬壯，吉","level":"L4","kw":["夷左股","受傷","拯馬","救援"],"i":["受傷受挫，但有強大後援支持，最終吉","腿部受傷或行動不便，但有良醫救治","感情受創，但有朋友或家人強力支持","財物受損，但有備用資金或保險理賠","投資受傷，但本金雄厚，可靠策略翻身","遇到有缺點的對象，但能溝通改善，順利解決","雖處下風，但有強力律師救援，轉危為安","房屋受損，但有修繕基金，修復吉祥"]},"36-3":{"name":"九三","text":"明夷于南狩，得其大首，不可疾貞","level":"L3","kw":["南狩","大首","除害","緩進"],"i":["在逆境中主動出擊，抓到禍首，但不能急於求成","查出重大病因，需慢慢治療，不可急","發現感情中的大問題，需慢慢解決","抓到財務漏洞或貪污者，止損成功","在低谷中抓到大黑馬，但需長期持有","終於遇到等待已久的重要對象，不可急躁","抓到對方把柄，勝訴在望，但程序漫長","在低檔區買到好房，增值潛力大，但需等待"]},"36-4":{"name":"六四","text":"入于左腹，獲明夷之心，于出門庭","level":"L4","kw":["入腹","知心","出門","避禍"],"i":["深入敵營了解內幕，看清真相後及時抽身","深入檢查發現隱疾，及時治療","看清對方真心（可能是負面的），決定離開","看清投資騙局，及時撤資","深入研究發現公司問題，獲利了結離場","發現對方動機不純，決定不交往","掌握對方核心證據，全身而退","發現房屋隱蔽瑕疵，決定放棄購買"]},"36-5":{"name":"六五","text":"箕子之明夷，利貞","level":"L2","kw":["箕子","裝瘋","晦藏","利貞"],"i":["環境極度黑暗，裝傻藏拙以自保，堅持正道有利","隱瞞病情以免親友擔心，獨自堅強面對","感情受委屈，表面裝作沒事，內心堅守真愛","財不露白，裝窮以避禍，利於守財","市場極差，隱藏實力，不做操作，等待時機","低調婚姻，不引人注目","面對強權，暫時隱忍，保留實力","低調置產，不張揚，利於保值"]},"36-6":{"name":"上六","text":"不明晦，初登于天，後入于地","level":"L9","kw":["不明","晦","登天","入地"],"i":["暴君下台，曾經不可一世，如今跌落谷底","迴光返照，看似好轉，實則惡化至極點","曾經轟轟烈烈，如今恩斷義絕，徹底破裂","曾是大富豪，如今破產潦倒，起落極大","股價衝天後崩盤，跌入深淵，血本無歸","發展關係了極昂貴的關係，結果完全沒價值","氣勢凌人者最終慘敗，下場淒涼","房價炒作上天，最終崩盤，跌入谷底"]},"37-1":{"name":"初九","text":"閑有家，悔亡","level":"L2","kw":["閑有家","規矩","防範","悔亡"],"i":["在開始時就立好規矩，管理嚴格，無後患","從小養成良好衛生習慣，預防疾病","交往初期建立原則，相處融洽無悔","建立家庭理財紀律，財務健康","設立嚴格的交易規則，避免虧損","設定婚姻原則，不輕率決定","防患於未然，合約寫清楚，避免訴訟","入住前先講好規矩（如合約），居住愉快"]},"37-2":{"name":"六二","text":"无攸遂，在中饋，貞吉","level":"L2","kw":["中饋","主婦","盡責","貞吉"],"i":["不追求外在功名，做好內部管理，大吉","注重飲食調理，腸胃健康","溫柔賢淑，照顧家庭，感情美滿","精打細算，持家有道，財富累積","保守穩健，像家庭主婦般精明，獲利","發展關係家庭基本需求，精挑細選","不主動興訟，守好本分，吉","將家裡佈置得溫馨舒適，大吉"]},"37-3":{"name":"九三","text":"家人嗃嗃，悔厲吉。婦子嘻嘻，終吝","level":"L4","kw":["嗃嗃","嚴厲","嘻嘻","放縱"],"i":["管理嚴格雖有抱怨但吉，管理鬆散最終失敗","嚴格自律雖辛苦但健康，放縱享樂終生病","對感情有要求雖有爭執但吉，太隨便則不好","理財嚴格吉，揮霍無度則貧窮","嚴格執行紀律吉，隨意操作則虧損","嚴格把關吉，隨意發展關係後悔","嚴陣以待吉，輕忽大意則敗訴","嚴格驗屋吉，隨便看看則後悔"]},"37-4":{"name":"六四","text":"富家，大吉","level":"L1","kw":["富家","興旺","大吉","聚財"],"i":["使公司或團隊興旺富裕，大吉大利","身體強健，精神富足，大吉","為家庭帶來財富與幸福，婚姻美滿","財運極佳，家業興旺，大富大貴","獲利豐厚，資產大幅增值","發展關係高人品耐久財，提升生活品質","勝訴並遇到賠償，大吉","買到旺宅，家運昌隆"]},"37-5":{"name":"九五","text":"王假有家，勿恤吉","level":"L1","kw":["王假","領導","勿恤","愛心"],"i":["領導者如一家之長，以愛心服人，大吉","身心和諧，無憂無慮，吉","雙方關係平等互愛，無需擔憂，幸福","財富運用得當，造福家人，吉","佈局完美，無需擔心，坐享其成","為家人發展關係禮物，充滿愛心","以德服人，不戰而屈人之兵","家庭和睦，房子充滿溫暖，吉"]},"37-6":{"name":"上九","text":"有孚威如，終吉","level":"L2","kw":["有孚","威如","誠信","威嚴"],"i":["誠信且有威嚴，受人敬重，最終大吉","嚴格堅持養生之道，身體健康","對感情忠誠且有原則，關係穩固","信用良好，受人信賴，財源廣進","堅持原則，不隨波逐流，最終獲利","找到有口碑的好對象，人品有保證","證據確鑿，威嚴不可犯，勝訴","產權清楚，交易過程嚴謹，吉"]},"38-1":{"name":"初九","text":"悔亡，喪馬勿逐，自復，見惡人无咎","level":"L4","kw":["喪馬","勿逐","惡人","溝通"],"i":["失去的機會不要追，會自己回來，與討厭的人合作無妨","小病痛不需過度治療，會自然好轉","分手不要追，對方會回頭，面對情敵要冷靜","小破財不需追究，錢會賺回來","錯過買點不要追高，機會會再來","小挫折不必在意，會出現","不需主動興訟，面對惡人保持冷靜無咎","看中的房子被買走不要追，會有更好的"]},"38-2":{"name":"九二","text":"遇主于巷，无咎","level":"L3","kw":["遇主","巷","巧遇","機緣"],"i":["在非正式場合巧遇貴人，遇到幫助","偶然遇到良醫，病情好轉","轉角遇到愛，意外的緣分","意外遇到賺錢資訊","無意中發現好標的，獲利","意外遇到好對象","庭外和解，或私下溝通解決","在巷弄中發現好房子，意外收穫"]},"38-3":{"name":"六三","text":"見輿曳，其牛擎，其人天且劓，无初有終","level":"L5","kw":["輿曳","刑罰","受辱","先苦後甘"],"i":["處處受制，遭受羞辱，但堅持到底會有結果","身體遭受刑罰般的痛苦，但最終能康復","遭受阻礙和誤解，甚至外貌受損，但結局還好","初期財務困難，受到拖累，最終解決","初期被套牢，過程痛苦，最後解套","遇到差的對象受氣，但最後分手成功","過程受盡屈辱，但最終還予清白","購屋過程受阻，糾紛多，最後成交"]},"38-4":{"name":"九四","text":"睽孤，遇元夫，交孚，厲无咎","level":"L3","kw":["睽孤","元夫","交孚","信任"],"i":["雖孤立無援，但遇到志同道合的強者，互信互助","久病孤獨，遇名醫相救","單身孤獨，遇到理想對象，誠信交往","孤軍奮戰，遇到金主支持","獨排眾議，遇到知音，共同獲利","找不到合意對象，朋友介紹良緣","孤立無援時遇到有力人士相助","獨自看房困難，遇到好仲介幫忙"]},"38-5":{"name":"六五","text":"悔亡，厥宗噬膚，往何咎","level":"L2","kw":["厥宗","噬膚","親近","容易"],"i":["內部團結，問題迎刃而解，大膽前進無咎","皮膚小毛病，很容易治癒","誤會冰釋，關係親密如初","家族互助，賺錢容易","跟隨核心主力，獲利容易","遇到好吃的食物或護膚品，滿意","自己人幫忙，輕鬆解決紛爭","親友幫忙，順利買到好房"]},"38-6":{"name":"上九","text":"睽孤，見豕負塗，載鬼一車，先張之弧，後說之弧，匪寇婚媾，往遇雨則吉","level":"L4","kw":["載鬼","疑神疑鬼","誤會","遇雨"],"i":["疑神疑鬼，把隊友當敵人，消除誤會後大吉","懷疑自己得重病，檢查後虛驚一場","嚴重誤會，以為對方變心，解釋清楚後感情更好","以為要破財，結果是發財機會","市場恐慌，以為崩盤，結果是洗盤，雨過天晴","以為遇到虛情假意，結果是真心","誤以為對方要加害，其實是來和解的","以為房子有問題，其實是誤會，成交吉"]},"39-1":{"name":"初六","text":"往蹇，來譽","level":"L3","kw":["往蹇","來譽","等待","明智"],"i":["前進有困難，退回來等待時機反而遇到讚譽","不宜外出或劇烈運動，靜養為佳","主動追求受阻，以退為進反而加分","投資時機不對，保留現金被視為明智","市場險惡，空手觀望是高明之舉","不發展關係不適合的關係，避免損失","暫緩提告，退一步海闊天空","現在不是買點，觀望等待"]},"39-2":{"name":"六二","text":"王臣蹇蹇，匪躬之故","level":"L2","kw":["蹇蹇","盡忠","匪躬","責任"],"i":["困難重重，為了職責鞠躬盡瘁，令人敬佩","為了照顧他人而累壞自己，需注意","為了家庭或對方付出，雖苦無怨","為了公家或他人財務奔波，自己無利","為了責任護盤，雖辛苦但值得尊敬","幫別人發展關係關係，辛苦奔波","為了正義挺身而出，雖陷困境但無愧","為了家人居住問題奔波，辛苦"]},"39-3":{"name":"九三","text":"往蹇，來反","level":"L3","kw":["往蹇","來反","回歸","內求"],"i":["外進困難，不如回到內部整頓，反求諸己","外求名醫無效，不如回家調養","向外尋求無果，回頭看身邊人","向外投資不利，回收資金固守本業","短線操作困難，回歸價值投資","外面找不到合適對象，回頭看看身邊人或舊識","訴訟不利，撤回反省","外面房子貴，不如整修舊屋"]},"39-4":{"name":"六四","text":"往蹇，來連","level":"L2","kw":["往蹇","來連","連結","人脈"],"i":["前進困難，退回來連結人脈，尋求盟友","尋求親友支持，共同對抗病魔","感情受阻，尋求親友團支援","獨資困難，尋求合夥人","單打獨鬥難，參加投資社群","相親力量大，連結他人發展關係","尋求聯合訴訟或集體支援","獨資買不起，找人合資或找家人支援"]},"39-5":{"name":"九五","text":"大蹇，朋來","level":"L2","kw":["大蹇","朋來","救援","團結"],"i":["面臨巨大困難，但會有朋友雪中送炭，吉","重病纏身，但有良醫好友相助","感情遭遇大難關，朋友幫忙度過","財務大危機，有金主救援","被嚴重套牢，但有資金挹注解圍","急需幫助，朋友介紹良緣","官司危急，有力人士出面協助","購屋資金缺口大，親友借款相助"]},"39-6":{"name":"上六","text":"往蹇，來碩，吉，利見大人","level":"L1","kw":["來碩","大人","大收穫","導師"],"i":["前進無路，退回來跟隨大師學習，收穫巨大","遇到國手級名醫，徹底治癒","聽從長輩意見，遇到美滿姻緣","跟隨投資大師，獲利豐碩","聽取專家建議，轉虧為盈，大賺","遇到大師級作品，價值連城","請到王牌律師，大獲全勝","經高人指點，買到風水寶地"]},"40-1":{"name":"初六","text":"无咎","level":"L4","kw":["无咎","剛柔","和解","平順"],"i":["困難剛解除，平安無事，休養生息","病癒初期，無大礙，多休息","誤會冰釋，關係恢復平靜","財務危機解除，收支平衡","解套離場，不賺不賠，平安","解決婚姻糾紛，無損失","和解結案，無過失","解決房屋問題，居住平安"]},"40-2":{"name":"九二","text":"田獲三狐，得黃矢，貞吉","level":"L2","kw":["獲三狐","黃矢","除害","正直"],"i":["除去身邊的小人，堅持正直，吉","除去多種併發症，身體好轉","斬斷爛桃花，感情回歸正軌","斬斷不當開支，財務轉好","出清表現差的股票，保留績優股","識破欺騙，遇到真心誠意","勝訴，讓小人受到懲罰","解決產權糾紛，驅逐惡房客"]},"40-3":{"name":"六三","text":"負且乘，致寇至，貞吝","level":"L8","kw":["負且乘","招搖","寇至","不配"],"i":["德不配位，小人得志，招來嫉妒和攻擊","身體虛弱卻逞強，招來病痛","條件不匹配，招來第三者或覬覦","露財炫富，招來小偷或強盜","資金不足卻開槓桿，招來斷頭風險","與身分不配的對象交往，被人嘲笑","無理取鬧，反而被告","買了負擔不起的豪宅，招來債務危機"]},"40-4":{"name":"九四","text":"解而拇，朋至斯孚","level":"L3","kw":["解拇","擺脫","小人","朋至"],"i":["擺脫依附的小人，志同道合的朋友就會到來","戒除壞習慣（如拇指癮），健康改善","與不適合的人分手，真愛才會出現","清理不良資產，優質資金就會進來","賣掉爛股，資金轉入好股","放下不適合的關係，迎接新機會","擺脫損友糾纏，遇到信任","處理掉問題房產，好運來到"]},"40-5":{"name":"六五","text":"君子維有解，吉，有孚于小人","level":"L1","kw":["有解","吉","感化","君子"],"i":["君子能夠解決難題，連小人都信服，吉","徹底解決病根，身體大好","解開所有心結，感情昇華","債務完全解決，信用恢復","完美解套獲利，市場信服","滿意的婚姻體驗，解決需求","圓滿解決紛爭，對方心服口服","解決所有房產疑難雜症，大吉"]},"40-6":{"name":"上六","text":"公用射隼于高墉之上，獲之，无不利","level":"L1","kw":["射隼","高墉","除惡","大快人心"],"i":["一舉剷除位高權重的禍首，大快人心，無往不利","切除重大腫瘤或病灶，重獲新生","果斷解決感情中的最大障礙","抓住大機會，一舉獲利","精準操作，在高點獲利了結","終於遇到等待已久的理想對象","擊敗強大的對手，大獲全勝","拿下難度極高但價值連城的房產"]},"41-1":{"name":"初九","text":"已事遄往，无咎，酌損之","level":"L3","kw":["已事","遄往","助人","停損"],"i":["放下手邊工作去幫助他人，雖有小犧牲但人緣佳","小病痛要趕快處理，犧牲一點時間換健康","為對方犧牲一點自我，感情會更好","小額捐款或幫助朋友，雖損財但積福","適度減碼，犧牲小利，換取安全","為了急需多付出代價，雖然辛苦但解決問題","吃點小虧趕快和解，省去大麻煩","稍微降價求售，能快速成交"]},"41-2":{"name":"九二","text":"利貞，征凶，弗損益之","level":"L4","kw":["利貞","弗損","益之","自保"],"i":["堅守崗位，不犧牲自己去迎合別人，吉","保養自己就是對家人最大的貢獻，不宜過勞","保持自我，不盲目遷就，感情才長久","守住本金，不隨意借貸給人，才是幫人","不割肉，堅持持有，不損就是益","不衝動決定大事，避免損失就是收穫","立場堅定，不輕易讓步，最終有利","不降價，堅持品質與價格，等待買家"]},"41-3":{"name":"六三","text":"三人行，則損一人；一人行，則得其友","level":"L5","kw":["三人行","損一人","專一","得友"],"i":["合夥人太多意見不合，不如兩人合作或獨資","看太多醫生反而混亂，專注一位良醫","三角關係必有一傷，專一才能遇到真愛","投資標的太多反而分散獲利，集中持股","策略太雜反而虧損，專注一種策略","發展關係不宜太過挑剔,專心經營一段感情","涉案人多反而複雜，單獨處理較好","意見太多難買房，聽從自己的直覺"]},"41-4":{"name":"六四","text":"損其疾，使遄有喜，无咎","level":"L2","kw":["損其疾","除病","有喜","改正"],"i":["改正缺點，消除團隊弊病，會有喜事","病痛消除，身體康復，可喜可賀","改掉壞脾氣，感情迅速加溫","砍掉虧損項目，財務狀況立即好轉","停損爛股，心情輕鬆，反而迎來好運","修好舊關係，不用發展關係新的，開心","消除誤會或爭執點，官司和解有喜","修繕房屋瑕疵，順利成交或入住"]},"41-5":{"name":"六五","text":"或益之，十朋之龜弗克違，元吉","level":"L1","kw":["或益之","十朋之龜","天助","大吉"],"i":["有如天助，遇到意想不到的大力支持，大吉","遇到稀世良藥或名醫救治，必癒","天作之合，眾人祝福，極度幸運","意外之財，中獎或遇到巨額資助","運氣極佳，怎麼投怎麼賺，大吉","遇到極佳良緣","形勢大逆轉，遇到強力證據，全勝","買到風水寶地，增值潛力無窮"]},"41-6":{"name":"上九","text":"弗損益之，无咎，貞吉，利有攸往，得臣无家","level":"L1","kw":["弗損益之","大益","得臣","惠而不費"],"i":["不用犧牲就能獲益，且能惠及他人，領袖格局","身心靈富足，健康長壽","雙方互補互助，不用犧牲誰，完美結合","利人利己的雙贏生意，財源廣進","長期投資遇到巨大回報，且造福社會","找到理想伴侶且全家和睦的好對象","雙贏的結局，不用賠償反而獲利","買到讓全家人都滿意的大房子"]},"42-1":{"name":"初九","text":"利用為大作，元吉，无咎","level":"L1","kw":["大作","大工程","元吉","開創"],"i":["時機成熟，適合推動大計畫、大工程，大吉","適合進行大手術或徹底的體質改造，成功","適合大膽追求，舉辦盛大婚禮","適合大額投資或創業，回報豐厚","重倉佈局主流股，獲利巨大","發展關係房產、車子等重要對象的好時機","適合發起重大訴訟，勝算極高","適合動土、蓋房、大規模裝修"]},"42-2":{"name":"六二","text":"或益之，十朋之龜弗克違，永貞吉。王用享于帝，吉","level":"L1","kw":["十朋之龜","天祐","享帝","神助"],"i":["遇到上天與眾人的幫助，長期吉利","如有神助，康復神速，長期健康","天賜良緣，感情堅定，白頭偕老","財運亨通，來自四面八方的財富","長期持有的標的帶來驚人回報","遇到傳家之寶，價值連城","天理昭彰，遇到公正判決","買到風水極佳的祖產或福地"]},"42-3":{"name":"六三","text":"益之用凶事，无咎。有孚中行，告公用圭","level":"L4","kw":["用凶事","救災","誠信","危機處理"],"i":["在危機中獲益（如救災、解決爛攤子），誠信則吉","因禍得福，因為生病反而養成好習慣","患難見真情，共同度過難關後感情更深","發災難財或危機入市，雖有爭議但無咎","在股市崩盤時進場撿便宜，大賺","接受有過往經歷或有缺陷的對象並包容，合適","據理力爭，向權威人士申訴，解決","購買受災或低價房產進行重建"]},"42-4":{"name":"六四","text":"中行，告公從。利用為依遷國","level":"L2","kw":["中行","遷國","搬遷","順從"],"i":["決策正確，上級支持，適合搬遷辦公室或轉職","適合換醫院或換個環境療養","適合搬家建立新家庭，或隨對方遷移","轉換跑道或投資市場，有利","將資金轉移到更有潛力的新市場","為了搬家而發展關係，順利","申請移轉管轄或更換律師，有利","大吉，非常適合搬家、移民或置產"]},"42-5":{"name":"九五","text":"有孚惠心，勿問元吉。有孚惠我德","level":"L1","kw":["惠心","勿問","感恩","回饋"],"i":["以誠信恩惠待人，不必占卜也是大吉，眾人回報","心地善良，心情愉快，自然大吉","真心付出不求回報，對方加倍愛你","做慈善積德，財富反而源源不絕","投資有社會責任的企業，獲利與名聲雙收","參與公益活動結識良緣，開心又吉利","以德報怨，感動對方，圓滿解決","鄰里關係極佳，居住環境充滿愛"]},"42-6":{"name":"上九","text":"莫益之，或擊之，立心勿恆，凶","level":"L9","kw":["莫益","擊之","貪婪","眾怒"],"i":["貪得無厭，沒人幫忙反而遭人攻擊，凶","過度索求，身體透支，遭疾病反擊","只知索取不知付出，對方反目成仇","貪心不足，招致詐騙或搶劫","貪婪追高，最後一棒，慘遭套牢","貪圖小利受傷害，遇到虛情假意悔恨無用","無理取鬧，引發眾怒，必敗","炒房過頭，遭政策打擊或資金斷鏈"]},"43-1":{"name":"初九","text":"壯于前趾，往不勝為咎","level":"L7","kw":["壯趾","不勝","躁進","失敗"],"i":["能力不足就想衝，必定失敗，自取其辱","腳部受傷，或體力未恢復就劇烈運動","時機未到就強行表白，失敗","本金不足就想做大生意，虧損","還沒看懂局勢就進場，被套牢","衝動選擇超出能力的對象，後悔","證據不足就提告，敗訴","頭期款不足硬要買，面臨斷頭"]},"43-2":{"name":"九二","text":"惕號，莫夜有戎，勿恤","level":"L3","kw":["惕號","莫夜","戒備","有驚無險"],"i":["隨時保持警惕，即使遇到突發狀況也能應對","對小病痛保持警覺，及早預防無大礙","對感情保持敏感，預防第三者，無事","做好風險控管，市場波動也不怕","設好停損點，夜裡也能安心睡覺","小心檢查婚姻，避免遇到有問題的對象","做好萬全準備，對方突襲也不怕","加強居家保全，居住安全無憂"]},"43-3":{"name":"九三","text":"壯于頄，有凶。君子夬夬，獨行遇雨，若濡有慍，无咎","level":"L4","kw":["獨行","遇雨","誤解","堅持"],"i":["決策不被理解，獨排眾議，雖受氣但無過錯","臉部受傷，或因堅持治療而被誤解","為了這段感情與眾人反目，雖苦但無悔","獨自投資冷門項目，被人嘲笑但無咎","逆勢操作，眾人恐慌我貪婪，雖有壓力但對","發展關係了別人看不懂的關係，自己喜歡就好","獨自面對訴訟，雖狼狽但站得住腳","買在無人問津區，雖被笑但有增值潛力"]},"43-4":{"name":"九四","text":"臀无膚，其行次且。牽羊悔亡，聞言不信","level":"L6","kw":["臀无膚","次且","不信","固執"],"i":["坐立難安，行動遲緩，不聽人勸導致失敗","坐骨神經痛或臀部受傷，不良於行","猶豫不決，又不聽勸，錯失良機","固執己見，錯失賺錢機會","被套牢坐立難安，不聽專家建議割肉","猶豫太久，想發展關係的沒了，後悔","處境尷尬，不聽律師建議，進退維谷","看房猶豫不決，好房被人搶走"]},"43-5":{"name":"九五","text":"莧陸夬夬，中行无咎","level":"L2","kw":["莧陸","決斷","中行","除惡務盡"],"i":["果斷清除身邊的小人，態度公正，無咎","果斷切除病灶或戒除惡習，身體好轉","果斷結束不倫戀或曖昧，回歸正軌","果斷處置不良資產，財務健康","果斷停利或停損，不拖泥帶水，吉","果斷決定，遇到好對象","速戰速決，公正處理，勝訴","果斷簽約，不被雜音干擾，買到好房"]},"43-6":{"name":"上六","text":"无號，終有凶","level":"L9","kw":["无號","凶","絕望","毀滅"],"i":["小人當道至極，或剛愎自用致死路，求救無門","病入膏肓，無藥可救，凶","緣分已盡，連爭吵的力氣都沒了，徹底結束","破產，一無所有，呼天不應","徹底崩盤，血本無歸，無翻身機會","遇到嚴重問題且無法挽回，悔恨無用","敗訴定讞，無力回天","房屋倒塌或被法拍，無家可歸"]},"44-1":{"name":"初六","text":"繫于金坭，貞吉。有攸往，見凶，羸豕孚蹢躅","level":"L4","kw":["繫金坭","制止","羸豕","防微杜漸"],"i":["一開始就要制止壞苗頭，不讓小人得逞，吉","發現小病徵兆立刻控制，否則惡化","爛桃花剛出現就要斬斷，否則後患無窮","抑制衝動的投資念頭，守財吉","看到苗頭不對立刻煞車，不進場","理性看待婚姻,不要為發展關係而發展關係","將糾紛消滅在萌芽狀態，吉","發現房子小問題立刻修，不買有疑慮的房"]},"44-2":{"name":"九二","text":"包有魚，无咎，不利賓","level":"L3","kw":["包有魚","獨佔","不分","私有"],"i":["將人才或資源收歸己用，不外流，無咎","懷孕之象，或肚子裡有東西（需檢查），保養吉","佔有慾強，不想公開戀情，適合地下情","私房錢藏得好，不借給別人，無咎","內線消息自己賺，不要分享給別人","遇到限量品，自己收藏","掌握關鍵證據，不公開，有利","買房自己住，不分租，吉"]},"44-3":{"name":"九三","text":"臀无膚，其行次且，厲，无大咎","level":"L4","kw":["臀无膚","次且","困難","無法相遇"],"i":["處境尷尬，想合作卻遇不到對象，雖苦無大害","坐立難安，行動不便，需休養","單相思，追不到對方，很痛苦但沒結果也好","資金卡住，想投投不了，反而避開風險","錯失買入機會，懊惱但沒虧錢","想要的對象無法得到，避免損失了","想告告不成，反而省了麻煩","看房辛苦但沒買成，避免了爛房"]},"44-4":{"name":"九四","text":"包无魚，起凶","level":"L7","kw":["包无魚","失民心","遠離","空虛"],"i":["脫離群眾，失去支持，底下沒人，凶","肚子空空，營養不良或胃病","對象跑了，或者根本沒人理你，孤單","口袋空空，錯失賺錢良機","賣飛了，眼睜睜看股價上漲，自己沒貨","去晚了，對象被搶走","證據遺失，敗訴","好房被買走，空手而回"]},"44-5":{"name":"九五","text":"以杞包瓜，含章，有隕自天","level":"L1","kw":["包瓜","含章","意外","天降"],"i":["沈穩內斂，不張揚，會有天降大任或好運","身體強健，內在充實，好運降臨","默默付出，不急於表達，天賜良緣","低調發大財，意外之財從天而降","長線佈局不張揚，突然暴漲","意外遇到珍稀良緣","不戰而勝，意外遇到有利轉機","意外繼承或買到增值巨大的房產"]},"44-6":{"name":"上九","text":"姤其角，吝，无咎","level":"L5","kw":["姤角","鑽牛角尖","孤傲","无咎"],"i":["性格孤傲，難以相處，雖然沒大錯但人緣差","頭部疾病或精神緊張，需放鬆","眼光太高，誰都看不上，單身","過於保守或挑剔，錯失機會，但也沒虧","死守高點或極端策略，沒賺到錢","眼光太高過於挑剔，錯失良緣仍單身","態度強硬，雖未敗訴但也無所得","對房子要求太高，買不到"]},"45-1":{"name":"初六","text":"有孚不終，乃亂乃萃，若號，一握為笑，勿恤，往无咎","level":"L4","kw":["乃亂","號","笑","聚散"],"i":["人心渙散，初期混亂，但呼號召集後能團結","情緒不穩，哭笑無常，需調節心理","分分合合，吵完又笑，最終還是再一起","財來財去，初期混亂，整理後轉好","市場震盪劇烈，先驚後喜，堅持住","婚姻過程混亂，但最後遇到喜歡的","初時混亂不利，據理力爭後轉危為安","交易過程波折，但最終能成交"]},"45-2":{"name":"六二","text":"引吉，无咎，孚乃利用禴","level":"L2","kw":["引吉","誠信","微薄","接納"],"i":["雖地位低，但有人引薦，誠信待人則吉","遇到良醫引薦，治療簡單有效","誠心感動對方，雖禮物微薄但被接納","遇到貴人指點財路，吉","跟隨大戶或專家操作，吉","朋友介紹良緣，條件適合","有人居中牽線調解，吉","透過熟人介紹買到好房"]},"45-3":{"name":"六三","text":"萃如，嗟如，无攸利，往无咎，小吝","level":"L6","kw":["嗟如","嘆息","孤獨","隨波逐流"],"i":["想加入圈子卻被排擠，嘆息，勉強跟隨無大害","鬱鬱寡歡，嘆氣傷神，身體微恙","單戀或被群體排擠，孤獨嘆息","看別人賺錢，自己沒份，嘆氣","追漲殺跌，總是慢一步，小虧","理想對象未能如願，只能退而求其次","孤立無援，雖無大禍但心裡苦","買不到喜歡的社區，勉強買別的"]},"45-4":{"name":"九四","text":"大吉，无咎","level":"L1","kw":["大吉","聚眾","成功","位高"],"i":["位高權重，能號召群眾，大吉大利","身體強健，精力充沛，大吉","廣受歡迎，桃花旺盛，大吉","財源滾滾，聚財能力強，大吉","投資組合完美，獲利豐厚","大發展關係，滿載而歸","勝訴，遇到大利益","買到增值潛力巨大的地產"]},"45-5":{"name":"九五","text":"萃有位，无咎。匪孚，元永貞，悔亡","level":"L2","kw":["有位","匪孚","永貞","領導"],"i":["身居高位但有人不服，需長期堅持正道才能服眾","身體底子好，但需長期保養才能完全健康","雖已結婚（有位），但需長期經營才能消除隔閡","財富多但根基未穩，需保守經營","雖有獲利但市場不穩，需長期持有","遇到條件優越的對象，初時覺得要求高，久了覺得值得","雖佔優勢但對方不服，需堅持到底","買了豪宅但入住率低，需等待發展"]},"45-6":{"name":"上六","text":"齎咨涕洟，无咎","level":"L5","kw":["涕洟","哭泣","悲傷","宣洩"],"i":["位高但孤獨，或退休後失落，哭泣宣洩後無咎","情緒抑鬱，大哭一場反而對身體好","為情所困，痛哭流涕，發洩出來就好","因損失而痛哭，但未傷及根本","虧損難過，但能記取教訓","發展關係貴了或被騙，難過","敗訴難過，或勝訴後喜極而泣","房產問題讓人操碎了心，想哭"]},"46-1":{"name":"初六","text":"允升，大吉","level":"L1","kw":["允升","准許","大吉","順利"],"i":["遇到上級准許晉升，起步順利，大吉","身體狀況開始好轉，適合提升體能","對方接受你的追求，關係升溫","財運開始上升，賺錢機會多","市場趨勢向上，進場大吉","婚姻能力提升，遇到良緣","訴求被法官採納，形勢大好","房產開始增值，或順利買房"]},"46-2":{"name":"九二","text":"孚乃利用禴，无咎","level":"L2","kw":["孚","禴","誠信","簡約"],"i":["憑藉誠信，雖無厚禮也能遇到晉升","誠心祈禱或簡單養生，效果好","真心相愛，不需鋪張浪費，感情好","小本經營，講究信用，獲利","誠實分析，穩健投資，無咎","不求奢華，只求實在，好","誠實陳述，不需花大錢請律師也能勝","簡單裝修，誠意出售，順利"]},"46-3":{"name":"九三","text":"升虛邑","level":"L2","kw":["升虛邑","無阻","順利","空城"],"i":["進入無人競爭的領域，晉升毫無阻礙","身體恢復極快，毫無阻力","追求對象無人競爭，輕鬆追到","賺錢輕鬆，如入無人之境","市場大漲，輕松獲利","去沒人的地方婚姻，輕鬆自在","對方缺席或無力反擊，勝訴","買到開發中的新市鎮，潛力大"]},"46-4":{"name":"六四","text":"王用亨于岐山，吉，无咎","level":"L1","kw":["亨岐山","祭祀","吉","誠心"],"i":["功成名就，舉行慶典，大吉","精神飽滿，適合心靈修養","感情修成正果，舉辦婚禮","財富累積到一定程度，回饋社會吉","獲利豐厚，吉","發展關係祭祀用品或禮品，吉","誠心和解，吉","在風水寶地置產，吉"]},"46-5":{"name":"六五","text":"貞吉，升階","level":"L1","kw":["升階","步步高","貞吉","穩健"],"i":["步步高升，穩健發展，大吉","健康狀況一階一階變好","感情穩定升溫，進入新階段","收入穩定增長，積少成多","階梯式上漲，穩賺不賠","婚姻升級，生活人品提高","案情逐步明朗，勝訴","換大房子，居住品質提升"]},"46-6":{"name":"上六","text":"冥升，利于不息之貞","level":"L4","kw":["冥升","昏頭","不息","堅持"],"i":["晉升過頭，有些昏頭轉向，需保持清醒堅持正道","過度進補或鍛鍊，需適可而止","愛得昏頭轉向，需冷靜思考","賺錢停不下來，小心過勞","漲勢過猛，盲目追高，需謹慎","婚姻狂，遇到停不下來，需節制","訴訟沒完沒了，需堅持到底","房價漲過頭，盲目追價有風險"]},"47-1":{"name":"初六","text":"臀困于株木，入于幽谷，三歲不覿","level":"L9","kw":["困株木","幽谷","不覿","絕境"],"i":["坐困愁城，被打入冷宮，長期無法翻身","久病臥床，精神抑鬱，長期不見好轉","感情陷入絕境，長期孤單或冷戰","破產，一貧如洗，長期無法翻身","嚴重套牢，資金凍結，數年無法解套","遇到完全不適合的對象，浪費時間","被關押或長期無法結案，不見天日","買到爛尾樓或荒郊野外，無法居住"]},"47-2":{"name":"九二","text":"困于酒食，朱紱方來，利用享祀，征凶，无咎","level":"L4","kw":["困酒食","朱紱","等待","享祀"],"i":["雖有吃有喝但不得志，等待重用，主動出擊凶","富貴病，飲食過度導致的疾病","被物質滿足但心靈空虛，等待真愛","衣食無憂但資金周轉不靈，不宜大投資","被套牢但有股息可領，不宜賣出","沈迷於吃喝享樂，造成遺憾","有官方介入，先祭祀求神，主動出擊凶","房子不錯但周邊環境受限，等待發展"]},"47-3":{"name":"六三","text":"困于石，據于蒺藜，入于其宮，不見其妻，凶","level":"L9","kw":["困石","蒺藜","不見妻","凶"],"i":["前有阻礙後有追兵，回家又沒溫暖，絕境凶","結石、骨刺或腫瘤，非常痛苦","感情破裂，甚至人去樓空，凶","陷入困境，資產被凍結，家破人亡","踩到地雷股，血本無歸，家庭失和","發展關係了無用且帶刺（危險）的關係，後悔","敗訴，家破人亡，凶","買到凶宅或有問題的房子，無法居住"]},"47-4":{"name":"九四","text":"來徐徐，困于金車，吝，有終","level":"L4","kw":["徐徐","困金車","富貴困","遲來"],"i":["救援來得慢，被富貴名利所困，但最終會好","慢性病，治療緩慢，但最終會好","豪門深似海，感情受物質束縛，但結局尚可","資金被卡在豪華項目上，周轉慢但有結果","投資藍籌股被套，解套慢但最終獲利","發展關係了豪車或奢侈品反而成負擔","因錢財糾紛拖延，最終解決","買豪宅壓力大，但最終能擁有"]},"47-5":{"name":"九五","text":"劓刖，困于赤紱，乃徐有說，利用祭祀","level":"L5","kw":["劓刖","赤紱","受刑","祭祀"],"i":["受到嚴厲懲罰或限制，雖有職位但無權，慢慢會解脫","動大手術（如截肢），需長期復健祈福","感情受重創，身心受傷，慢慢會走出來","資產大幅縮水，如被割肉，需慢慢恢復","慘賠出場，元氣大傷，需時間平復","感情受重創，付出慘痛代價，需時間療傷","遭受刑罰，但最終遇到赦免或解脫","房屋受損嚴重，需慢慢修繕"]},"47-6":{"name":"上六","text":"困于葛藟，于臲卼，曰動悔。有悔，征吉","level":"L3","kw":["葛藟","動悔","覺悟","解脫"],"i":["被瑣事纏身，動彈不得，一旦覺悟行動就能解脫吉","久病纏身，決心改變生活方式就能好轉","被爛桃花糾纏，下定決心分手就吉","被債務糾纏，決心處理就能解決","猶豫不決被套，痛下決心賣出反而吉","被甜言蜜語者糾纏，果斷拒絕吉","官司纏身，主動和解或反擊吉","產權糾紛複雜，快刀斬亂麻吉"]},"48-1":{"name":"初六","text":"井泥不食，舊井无禽","level":"L8","kw":["井泥","不食","廢棄","無用"],"i":["能力退化，無人問津，如廢井般被遺棄","體內淤積毒素，身體機能衰退","感情生活如死水，沒人追求","資產貶值成廢紙，毫無價值","投資冷門股，流動性差，沒人買","遇到過期或無用的關係","證據失效，無人理會，敗訴","房子太舊無法居住，也租不出去"]},"48-2":{"name":"九二","text":"井谷射鮒，甕敝漏","level":"L7","kw":["射鮒","漏","破損","浪費"],"i":["有能力但用錯地方，或工具損壞無法發揮","身體漏氣（如腹瀉、出血），元氣外洩","所託非人，感情付出如漏水般流失","漏財，錢賺了都存不住","資金漏洞，獲利被手續費或虧損吃掉","遇到有缺陷的關係","律師無能，證據漏洞百出","房屋漏水，修繕困難"]},"48-3":{"name":"九三","text":"井渫不食，為我心惻，可用汲，王明，並受其福","level":"L4","kw":["井渫","不食","可惜","明王"],"i":["懷才不遇，雖有能力但無人賞識，等待明主","身體已經調養好，但還沒派上用場","條件很好但單身，令人惋惜，等待緣分","有存款但不敢花，或有資源沒開發","好股票被低估，沒人買，等待價值發現","好對象未被發現，可以把握機會","有理但沒人信，需遇清官","好房子沒人住，可惜"]},"48-4":{"name":"六四","text":"井甃，无咎","level":"L3","kw":["井甃","修井","整頓","无咎"],"i":["進修學習，整理內部，暫時沒有表現但無咎","進行手術或治療修復身體，休養中","整理心情，修復感情創傷","重新規劃理財，修補財務漏洞","重整投資組合，暫停交易","修復舊有關係，暫不尋找新對象","整理證據，修補漏洞","房屋裝修維護，增值"]},"48-5":{"name":"九五","text":"井冽，寒泉食","level":"L1","kw":["井冽","寒泉","甘甜","貢獻"],"i":["能力卓越，品德高尚，如甘泉般造福眾人，大吉","身體極佳，精神清爽","感情純潔美好，令人心曠神怡","財富來源清正，受人羨慕","投資績優股，獲利豐厚且穩定","遇到高人品的婚姻，滿意","清者自清，勝訴","擁有優質水源或環境的房產，吉"]},"48-6":{"name":"上六","text":"井收勿幕，有孚元吉","level":"L1","kw":["勿幕","開放","有孚","大成"],"i":["功德圓滿，無私分享成果，大吉","健康長壽，並能幫助他人健康","感情修成正果，且能祝福他人","財富自由，樂善好施，大吉","獲利了結，分享經驗，大吉","遇到好對象分享給大家","圓滿解決，樹立典範","房產極佳，開放共享或傳家"]},"49-1":{"name":"初九","text":"鞏用黃牛之革","level":"L4","kw":["鞏","黃牛革","束縛","時機未到"],"i":["時機未成熟，不宜改革，先穩固基礎","病情需保守治療，不宜大動干戈","感情不宜急於改變現狀，維持穩定","資金被鎖死，不能動用","不宜換股操作，抱牢不動","不宜尋找新對象，珍惜舊有關係","受制於人，無法動彈，忍耐","不宜買賣或裝修，維持現狀"]},"49-2":{"name":"六二","text":"已日乃革之，征吉，无咎","level":"L2","kw":["已日","革之","時機成熟","行動"],"i":["改革時機成熟，大膽行動，吉","適合進行手術或改變生活方式，吉","適合告白、求婚或改變相處模式","調整資產配置，轉換跑道，吉","換股操作，賣舊買新，吉","分手再戀，發展關係更好的對象","發起訴訟或改變策略，吉","裝修或換房，吉"]},"49-3":{"name":"九三","text":"征凶，貞厲，革言三就，有孚","level":"L4","kw":["革言三就","審慎","討論","有孚"],"i":["躁進改革凶，需反覆討論三次確認後再做","治療方案需多方諮詢，不可貿然進行","改變關係需深思熟慮，溝通多次才行","投資計畫需反覆審查，不可衝動","市場消息需多方求證，確認後再進場","慎重考慮對象,三思而後行再決定","訴訟策略需反覆推敲，小心謹慎","買房需看三次以上，多方打聽"]},"49-4":{"name":"九四","text":"悔亡，有孚改命，吉","level":"L1","kw":["改命","悔亡","大變革","信任"],"i":["進行重大改革，改變命運，大吉","徹底改變體質，重獲新生","感情發生重大轉折，結局美好","命運翻轉，由窮變富，吉","抓住大趨勢，徹底改變投資績效","發展關係了改變生活的關係，無悔","逆轉勝，改變判決","風水輪流轉，買到旺宅改運"]},"49-5":{"name":"九五","text":"大人虎變，未占有孚","level":"L1","kw":["虎變","威猛","顯赫","不占"],"i":["如老虎換毛般煥然一新，事業大成，不必占卜","身體變得強壯威猛，氣色極佳","魅力大增，感情生活精彩","財富暴增，顯赫一時","績效驚人，如虎添翼","發展關係高貴、有氣勢的婚姻","氣勢如虹，勝券在握","房子裝修得金碧輝煌，氣派"]},"49-6":{"name":"上六","text":"君子豹變，小人革面，征凶，居貞吉","level":"L3","kw":["豹變","革面","收尾","守成"],"i":["改革完成，君子更加優雅，小人表面順從，宜守成","身體好轉，需持續保養，不宜再折騰","關係改善，對方態度轉變，維持現狀吉","獲利穩定，不宜再冒險投資","趨勢確立，順勢而為，不宜頻繁操作","遇到滿意的關係，不用再換了","對方表面服輸，見好就收吉，再告凶","裝修完成，安居樂業吉，再改凶"]},"50-1":{"name":"初六","text":"鼎顛趾，利出否，得妾以其子，无咎","level":"L3","kw":["顛趾","出否","除舊","无咎"],"i":["顛覆舊有體制，清除垃圾，雖然混亂但無咎","排出體內毒素（如嘔吐腹瀉），去舊生新","結束舊的不適合的關係，才有新開始","清理不良資產，重新出發","賣掉爛股，重新佈局","把舊關係丟掉或賣掉，發展關係新的","推翻之前的錯誤論點，重新辯護","大掃除，清理垃圾，吉"]},"50-2":{"name":"九二","text":"鼎有實，我仇有疾，不我能即，吉","level":"L2","kw":["鼎有實","充實","仇有疾","吉"],"i":["有真才實學，遭人嫉妒，但對方奈何不了你，吉","身體底子好，病毒無法入侵","感情堅固，第三者無法破壞","財庫充實，小人無法覬覦","持有績優股，市場波動影響不了你","遇到真心實意的良緣","證據確鑿，對方無法反駁，吉","房子結構堅固，風吹雨打都不怕"]},"50-3":{"name":"九三","text":"鼎耳革，其行塞，雉膏不食，方雨虧悔，終吉","level":"L4","kw":["鼎耳革","失職","不食","終吉"],"i":["懷才不遇，職位變動導致無法發揮，堅持終吉","身體不適，吃不下美味，調養後會好","感情受阻，無法溝通，誤會消除後吉","資金被凍結，無法動用，最終會解凍","好股票被低估，暫時不漲，長期看好","發展關係了好對象卻用不上，以後會用到","進展受阻，更換策略後勝訴","好房賣不掉，等待時機終成交"]},"50-4":{"name":"九四","text":"鼎折足，覆公餗，其形渥，凶","level":"L9","kw":["折足","覆餗","搞砸","凶"],"i":["能力不足承擔重任，搞砸事情，身敗名裂","腿部骨折，或身體崩潰，凶","搞砸關係，覆水難收，極為狼狽","委託非人，財產被揮霍一空","槓桿過大斷頭，傾家蕩產","遇到有嚴重缺陷的對象，甚至受到傷害","敗訴且名譽掃地","房子地基塌陷，嚴重損壞"]},"50-5":{"name":"六五","text":"鼎黃耳金鉉，利貞","level":"L1","kw":["黃耳","金鉉","中正","尊貴"],"i":["身居高位，任用賢能，事業鼎盛，利貞","身體金貴，保養得宜，健康","對象條件極佳，感情尊貴穩固","財富豐厚，且有守財之道","投資黃金或貴重金屬，獲利","發展關係貴重或優質對象，吉","遇到有力人士支持，勝算大","買到豪宅或精華地段，保值"]},"50-6":{"name":"上九","text":"鼎玉鉉，大吉，无不利","level":"L1","kw":["玉鉉","溫潤","大吉","完美"],"i":["剛柔並濟，事業達到完美境界，大吉","身心靈完美和諧，健康長壽","感情溫潤如玉，完美無瑕","富貴雙全，大吉大利","投資藝術品或玉石，大賺","遇到理想對象，愛不釋手","圓滿解決，雙方都滿意","買到完美的傳家之宅"]},"51-1":{"name":"初九","text":"震來虩虩，後笑言啞啞，吉","level":"L2","kw":["震來","虩虩","笑言","先驚後喜"],"i":["突發變故讓人驚恐，但處理得當，結果大吉","突發急症，嚇出一身冷汗，但檢查後無礙","發生爭吵或意外，以為要分手，結果感情更好","股市暴跌或財務衝擊，驚嚇後反彈獲利","市場劇烈震盪，先跌後漲，虛驚一場","以為發展關係錯或遺失，結果失而復得","收到傳票或律師函，驚嚇後順利解決","房子發生小意外（如地震），檢查後結構無損"]},"51-2":{"name":"六二","text":"震來厲，億喪貝，躋于九陵，勿逐，七日得","level":"L4","kw":["喪貝","勿逐","七日得","暫失"],"i":["遭逢巨變，損失金錢，暫避風頭，之後會失而復得","重病或受傷，需暫時休養（上山），七日後好轉","感情受挫，對方暫時離開，不要追，會回來","破財，損失慘重，但不要急著追回，會回流","被套牢或虧損，暫時不要操作，等待反彈","關係遺失或被搶，不要追，會找回","暫時失利，損失金錢，過段時間有轉機","房價下跌或交易告吹，觀望一陣子會好轉"]},"51-3":{"name":"六三","text":"震蘇蘇，震行无眚","level":"L4","kw":["蘇蘇","恐懼","无眚","平安"],"i":["嚇得六神無主，但只要繼續行動，就無災禍","神經衰弱，驚恐不安，但身體無大礙","對感情缺乏安全感，疑神疑鬼，但無實質問題","被市場波動嚇到不敢動，其實沒事","心態不穩，容易恐慌賣出，穩住就無災","擔心遇到虛情假意或被騙，其實過慮了","被對方氣勢嚇到，但實際無險","擔心房子有問題，檢查後沒事"]},"51-4":{"name":"九四","text":"震遂泥","level":"L7","kw":["遂泥","陷入","無力","癱瘓"],"i":["遭遇打擊，陷入泥沼，無力振作，前途黯淡","中風或癱瘓，身體機能喪失，行動不便","感情陷入僵局，無力改變現狀，冷淡","資金被凍結，週轉不靈，陷入困境","深陷泥沼，動彈不得，虧損嚴重","發展關係了無法脫手的爛關係","案情膠著，陷入泥淖，無法結案","房子地基下陷或陷入產權糾紛"]},"51-5":{"name":"六五","text":"震往來厲，億无喪，有事","level":"L3","kw":["往來厲","无喪","有事","忙碌"],"i":["危機接踵而來，忙於應付，雖危險但無大損失","舊病復發，來來去去，雖煩人但無大礙","爭吵不斷，分分合合，但不會真的分手","資金大進大出，風險高，但保本","震盪劇烈，上沖下洗，沒賠錢但很累","為了婚姻奔波，雖然累但成功了","官司反覆，忙於應訴，無大損失","為了房子修繕或交易奔波，有事但無損"]},"51-6":{"name":"上六","text":"震索索，視矍矍，征凶。震不于其躬，于其鄰，无咎。婚媾有言","level":"L5","kw":["索索","征凶","鄰","警惕"],"i":["恐慌至極，前進凶。災難發生在同事身上，自己警惕則無咎","神經過敏，看別人病倒要警惕，自己保養則吉","看到別人離婚或分手，自己要警惕，婚事有爭議","看到別人破產要警惕，自己保守則吉，進攻凶","隔壁老王賠光了，自己趕快收手，吉","朋友交往後悔，自己就別嘗試了","同案被告敗訴，自己要趕快和解","鄰居失火或房價跌，自己趕快加強防護"]},"52-1":{"name":"初六","text":"艮其趾，无咎，利永貞","level":"L3","kw":["艮趾","止步","无咎","初止"],"i":["在錯誤開始前就停下腳步，無咎，堅持正道吉","發現腳部或初期症狀，立即停止不良習慣","這段感情不該開始，立即停止，吉","不要衝動投資，停下來思考，吉","觀望，不進場，無咎","忍住不發展關係，無咎","還沒提告就停止，省去麻煩","暫停購屋計畫，吉"]},"52-2":{"name":"六二","text":"艮其腓，不拯其隨，其心不快","level":"L6","kw":["艮腓","不拯","不快","被動"],"i":["想停停不下來，被上司或團隊拖著走，心裡不爽","腿部肌肉僵硬，行動不便，心情鬱悶","想分手分不掉，被對方拖著走，不快樂","資金被套住，想撤撤不了，不快","想停損但手軟，眼睜睜看著虧損，不快","陪伴他人，被迫接受關係，不爽","身不由己捲入官司，想停無法停","房產交易卡住，進退兩難"]},"52-3":{"name":"九三","text":"艮其限，列其夤，厲薰心","level":"L8","kw":["艮限","列夤","薰心","劇痛"],"i":["強行停止，腰斬計畫，導致團隊分裂，痛苦焦慮","腰背劇痛，或心臟病發，危險","強行分手，像撕裂身體一樣痛苦，心如刀割","資金鏈斷裂，腰斬，極度焦慮","腰斬式暴跌，痛徹心扉","發展關係了極貴的關係卻壞了，心痛","官司卡在關鍵處，焦慮焚心","房子結構斷裂或腰斬法拍，凶"]},"52-4":{"name":"六四","text":"艮其身，无咎","level":"L3","kw":["艮身","潔身","自愛","无咎"],"i":["潔身自愛，獨善其身，不捲入是非，無咎","注意上半身保養，靜坐養生，吉","守身如玉，暫時單身或保持距離，無咎","保守理財，不貪不求，平安","空手觀望，保住本金，無咎","婚姻需務實考慮,避免不切實際的幻想","置身事外，不被牽連","自住無咎，不宜投資"]},"52-5":{"name":"六五","text":"艮其輔，言有序，悔亡","level":"L2","kw":["艮輔","言有序","慎言","悔亡"],"i":["謹言慎行，說話有條理，悔恨消失，吉","病從口入，注意飲食和說話衛生","溝通有節制，不說傷人的話，感情好","不亂聽小道消息，不亂說商業機密","不聽信謠言，理性分析，悔亡","不被話術欺騙，理性婚姻","法庭上說話謹慎，有條理，有利","交易談判謹慎，合約清楚，吉"]},"52-6":{"name":"上九","text":"敦艮，吉","level":"L1","kw":["敦艮","厚重","吉","圓滿"],"i":["功成身退，厚道穩重，結局圓滿大吉","身心安泰，像山一樣穩重健康","感情深厚穩定，白頭偕老","積蓄豐厚，晚年富足","長期持有，獲利穩健豐厚","遇到可靠穩重的好對象","圓滿解決，穩如泰山","買到穩固的資產，傳家之寶"]},"53-1":{"name":"初六","text":"鴻漸于干，小子厲，有言，无咎","level":"L4","kw":["鴻漸","干","小子厲","閒言"],"i":["剛入職場或新環境，地位低受排擠，小心謹慎無咎","小孩生病，或初期小病，小心照顧無咎","剛開始交往，會有一些閒言閒語，堅持無咎","剛開始投資，獲利微薄，勿急","初期震盪，有人看衰，堅持無咎","發展關係這關係有人反對，但沒問題","剛開始有些不利的言語，小心應對","在水邊或邊緣地帶買房，需謹慎"]},"53-2":{"name":"六二","text":"鴻漸于磐，飲食衎衎，吉","level":"L2","kw":["磐","飲食","衎衎","安穩"],"i":["事業站穩腳跟，如在磐石上，待遇優厚，吉","胃口好，營養充足，身體安康","感情穩定，生活富足快樂，吉","收入穩定豐厚，衣食無憂","投資穩健如磐石，坐領股息","遇到穩固長久的關係，開心相處","立場穩固，心情輕鬆，吉","買到地基穩固的好房，居住安樂"]},"53-3":{"name":"九三","text":"鴻漸于陸，夫征不復，婦孕不育，凶，利御寇","level":"L8","kw":["陸","不復","不育","分離"],"i":["冒進導致失敗，離家遠行不歸，團隊離散","流產、不孕或丈夫生病，凶","丈夫外遇不回，妻子流產，感情破裂","投資失利，本金一去不回","肉包子打狗，有去無回","遇到有缺陷的對象，分手無門","敗訴，人財兩失，防禦為上","買到不毛之地，無法開發"]},"53-4":{"name":"六四","text":"鴻漸于木，或得其桷，无咎","level":"L4","kw":["木","桷","棲身","暫安"],"i":["處境危險，但找到暫時的棲身之所，無咎","病情不穩，但找到合適的療法控制","感情不穩，但暫時有個依靠","收入不穩，但有兼職可餬口","市場動盪，找到避風港","雖不滿意但堪用，湊合著用","暫時和解或緩刑，無咎","租房或暫居，非長久之計"]},"53-5":{"name":"九五","text":"鴻漸于陵，婦三歲不孕，終莫之勝，吉","level":"L3","kw":["陵","三歲","終吉","團圓"],"i":["達到高峰但遭嫉妒排擠，堅持三年終獲成功","久病不癒，但最終能康復","長期分離或誤會，最終排除萬難團圓，吉","長期投資，初期無獲利，最終大賺","套牢三年，最終解套獲利","等待很久，終於遇到理想對象","纏訟多年，最終勝訴","看房很久，終於買到理想的高處房產"]},"53-6":{"name":"上九","text":"鴻漸于陸，其羽可用為儀，吉","level":"L1","kw":["羽","儀","模範","清高"],"i":["功成名就，成為行業楷模，大吉","仙風道骨，精神超脫，健康","感情昇華，成為神仙眷侶，受人羨慕","名利雙收，財富清白，吉","投資眼光獨到，成為典範","遇到極具品味的藝術品","勝訴並建立判決先例，吉","買到地標性建築或景觀宅"]},"54-1":{"name":"初九","text":"歸妹以娣，跛能履，征吉","level":"L3","kw":["娣","跛能履","輔佐","守分"],"i":["適合作為副手或輔助角色，不宜當頭，吉","身體有小缺陷（如跛腳），但仍能運作","當側室或配角，或者姐弟戀，守分則吉","副業收入比主業好，或合夥當小股東","跟隨大戶操作，喝湯吃肉，吉","發展關係有過往經歷或條件稍差，實際可行","作為從犯或證人，處境尚可","買附屬建物或小套房，吉"]},"54-2":{"name":"九二","text":"眇能視，利幽人之貞","level":"L4","kw":["眇能視","幽人","守節","獨處"],"i":["職位低微或被冷落，但堅守崗位，獨善其身","視力減退或有隱疾，宜靜養","單戀或配偶不忠，但堅守貞節，不願改變","財運平平，守財為上","眼光有侷限，宜保守","看不清婚姻好壞，不發展關係為宜","證據不足，處於劣勢，保持沈默有利","採光不佳的幽暗房子，不宜投資"]},"54-3":{"name":"六三","text":"歸妹以須，反歸以娣","level":"L7","kw":["須","反歸","墮落","不被接受"],"i":["急於求成反而自貶身價，想當正職卻變成臨時工","整形失敗，或用藥錯誤","為了結婚不擇手段，反而被降級為備胎","貪小便宜吃大虧，得不償失","投機取巧反而虧損","發展關係了條件稍差充當正品，被識破","弄巧成拙，處境更糟","想買豪宅買不起，最後買了爛房"]},"54-4":{"name":"九四","text":"歸妹愆期，遲歸有時","level":"L3","kw":["愆期","遲歸","等待","良緣"],"i":["大器晚成，不要急，等待最好的時機","病程較長，需耐心治療，最終會好","晚婚之象，寧缺勿濫，等待真命天子","財富來得晚，需要時間累積","長期持有，延後獲利了結","現在沒貨，等待下一批更好的","拖延戰術，等待有利時機","現在房市不好，延後購屋計畫"]},"54-5":{"name":"六五","text":"帝乙歸妹，其君之袂，不如其娣之袂良，月幾望，吉","level":"L1","kw":["帝乙","袂","樸素","內在美"],"i":["身分高貴但謙虛樸素，不重外表重實力，大吉","不靠化妝品，身體底子好，健康","下嫁（或娶條件差的），注重內在美，婚姻美滿","財不露白，穿著樸素的大富豪","選擇樸實無華但體質好的績優股","不發展關係名門，買實用良緣，吉","有理不在聲高，勝訴","外觀樸素但內裝豪華的房子，吉"]},"54-6":{"name":"上六","text":"女承筐无實，士刲羊无血，无攸利","level":"L9","kw":["无實","无血","虛假","一場空"],"i":["有名無實，空殼公司，一場空","虛弱無血色，不孕，或手術失敗","虛情假意，有夫妻之名無夫妻之實，離婚","空頭支票，投資詐騙，血本無歸","紙上富貴，無法變現","遇到虛假承諾或虛情假意","兩敗俱傷，什麼都沒得到","產權不清，無法過戶，一場空"]},"55-1":{"name":"初九","text":"遇其配主，雖旬无咎，往有尚","level":"L2","kw":["配主","合作","旬","无咎"],"i":["遇到極佳的合作夥伴，雖短暫（旬）但成果豐碩","遇到良醫，療程雖短但有效","一見鍾情，天作之合，雖然相處時間短但很好","與人合夥賺快錢，吉","短期操作，跟對主力，獲利","遇到搭配完美的婚姻","與對方和解，雙贏","買到格局完美的房子"]},"55-2":{"name":"六二","text":"豐其蔀，日中見斗，往得疑疾，有孚發若，吉","level":"L4","kw":["蔀","見斗","疑疾","誠信"],"i":["被小人遮蔽，才華被埋沒，只要保持誠信，終吉","病情隱晦不明，容易被誤診，需詳細檢查","被誤會或被第三者遮蔽，堅持真誠可化解","黑箱作業，帳目不清，需查明","市場資訊不明，不要盲目行動，守信吉","婚姻來歷不明，小心發展關係","被誣陷，需提出有力證據證明清白","採光不佳，屋內陰暗，需改善"]},"55-3":{"name":"九三","text":"豐其沛，日中見沫，折其右肱，无咎","level":"L7","kw":["沛","見沫","折肱","受損"],"i":["局勢極度黑暗，得力助手（右肱）折損，無能為力","右手骨折或受傷，重病","感情受到嚴重打擊，分手或受傷","損失慘重，斷臂求生","主力受傷，市場崩盤，不可進場","遇到壞掉的關係，無法使用","律師無能或證據被毀，不利","房屋結構受損（如樑柱斷裂），危險"]},"55-4":{"name":"九四","text":"豐其蔀，日中見斗，遇其夷主，吉","level":"L3","kw":["蔀","夷主","遇合","吉"],"i":["雖處黑暗中，但遇到同樣遭遇的伙伴，合作吉","久病遇良醫（可能也是久病成良醫的人）","同病相憐，惺惺相惜，感情發展吉","黑暗中找到一線生機，有人幫忙","在熊市中找到同好，互相打氣","在意想不到的地方遇到好對象","遇到好的幫手，案情轉機","在冷門地段買到好房"]},"55-5":{"name":"六五","text":"來章，有慶譽，吉","level":"L1","kw":["來章","慶譽","光彩","大吉"],"i":["招攬賢才，事業達到頂峰，充滿光彩與喜慶","身體狀況極佳，容光煥發","喜事臨門，結婚生子，受人祝福","財運極旺，名利雙收","獲利豐厚，成為傳奇","遇到令人稱羨的對象理想對象","勝訴，遇到名譽賠償","買到豪宅，張燈結彩"]},"55-6":{"name":"上六","text":"豐其屋，蔀其家，窺其戶，闃其无 人，三歲不覿，凶","level":"L9","kw":["豐屋","无人","孤獨","凶"],"i":["自以為是，自我封閉，導致眾叛親離，凶","自閉症，或孤獨死，身心狀態極差","住豪宅但沒人愛，孤獨一生","守著財富卻沒人分享，孤獨","慘遭套牢，無人接盤，孤獨持有","發展關係了堆積如山的關係卻沒人用","眾叛親離，沒人幫忙，必敗","豪宅空置，無人居住，荒廢凶"]},"56-1":{"name":"初六","text":"旅瑣瑣，斯其所取災","level":"L7","kw":["瑣瑣","斤斤計較","取災","小氣"],"i":["心胸狹窄，斤斤計較，在外地工作惹人厭，自取其災","過度計較小病痛，反而弄巧成拙","太小氣，計較誰付錢，導致分手","貪小便宜吃大虧，因小失大","為了省手續費錯失大行情，或貪小利被套","遇到條件很差的對象，結果引起火災或受傷","因為小事興訟，反而惹禍上身","貪便宜買爛房，後患無窮"]},"56-2":{"name":"六二","text":"旅即次，懷其資，得童僕貞","level":"L2","kw":["即次","懷資","得僕","安穩"],"i":["在外地站穩腳跟，資金充足，有得力助手，吉","在異地找到好的醫院和看護，安養","旅途中遇到伴侶，或感情穩定","出門在外財運好，錢包滿滿","投資海外市場獲利，資金充裕","條件充足有閒，有人幫忙協助，開心","資金充足，有律師協助，安穩","買到好的度假屋或旅館，有管家打理"]},"56-3":{"name":"九三","text":"旅焚其次，喪其童僕，貞厲","level":"L8","kw":["焚次","喪僕","傲慢","危險"],"i":["在外地太過囂張，得罪人，住所被燒，助手跑了，凶","發高燒，或照顧者離去，危險","脾氣太壞，把伴侶氣跑了，孤單","露白招災，被搶劫或火災，損失慘重","過於自信，慘遭滑鐵盧，資金歸零","遇到危險對象，或婚姻時感情被騙","失去律師，處境危險","房子失火，或租客跑了"]},"56-4":{"name":"九四","text":"旅于處，得其資斧，我心不快","level":"L4","kw":["旅于處","資斧","不快","未定"],"i":["暫時安定，也有錢，但不是家鄉，心裡不踏實","身體狀況尚可，但精神抑鬱","有對象但感覺不對，雖在一起但不快樂","賺了錢但沒地方花，或者賺得不開心","獲利了但心裡不安，想落袋為安","發展關係了關係但不喜歡，後悔","暫時沒事，但隱憂未除","住在租來的豪華房子，始終不是自己的家"]},"56-5":{"name":"六五","text":"射雉一矢亡，終以譽命","level":"L2","kw":["射雉","一矢亡","獲譽","成功"],"i":["雖付出小代價（一矢），但遇到極大名聲與成功","花錢治病，終於康復","付出一點代價，追到理想對象","花小錢賺大錢，名利雙收","停損一小部分，換來整體大賺","投入感情遇到令人讚賞的好對象","花錢消災，遇到好名聲","花錢裝修，房子增值"]},"56-6":{"name":"上九","text":"鳥焚其巢，旅人先笑後號啕，喪牛于易，凶","level":"L9","kw":["焚巢","笑後號","喪牛","樂極生悲"],"i":["得意忘形，結果老巢被燒，樂極生悲，凶","以為康復了亂搞，結果病情急轉直下","以為穩定了就傲慢，結果對方決絕離開","暴發後揮霍，最終破產痛哭","大賺後不走，結果崩盤歸零","發展關係了豪宅結果失火，一場空","以為贏了，結果被反告慘敗","房子全毀，資產歸零"]},"57-1":{"name":"初六","text":"進退，利武人之貞","level":"L4","kw":["進退","猶豫","武人","果斷"],"i":["優柔寡斷，進退兩難，應該像軍人一樣果斷才吉","懷疑醫生，換來換去，應果斷治療","猶豫不決，三心二意，應快刀斬亂麻","想買又想賣，錯失良機","操作猶豫，被雙巴，應果斷停損或進場","逛了半天發展關係不下去，損失時間","猶豫是否和解，應果斷決定","看房猶豫，好房被搶"]},"57-2":{"name":"九二","text":"巽在床下，用史巫紛若，吉，无咎","level":"L3","kw":["床下","史巫","謙卑","祈禱"],"i":["過於謙卑甚至卑躬屈膝，透過祝禱或誠意感動上天，吉","久病臥床，透過宗教或心理療法好轉","姿態極低，極力挽回，誠意感動對方","誠心求財，或從事宗教、身心靈產業吉","保守低調，聽取專家意見，吉","發展關係宗教用品或身心靈課程","姿態放低，尋求調解，吉","房產位置隱蔽，或設有神壇，吉"]},"57-3":{"name":"九三","text":"頻巽，吝","level":"L6","kw":["頻巽","反覆","羞辱","沒主見"],"i":["一再順從，沒有主見，被人看不起，羞辱","病情反覆，治療無效","毫無尊嚴地討好對方，只會被踐踏","耳根子軟，亂聽消息，虧損","頻繁進出，手續費虧損","發展關係了退，退了買，長輩討厭","反覆無常，法官厭惡，不利","決定變來變去，買不到房"]},"57-4":{"name":"六四","text":"悔亡，田獲三品","level":"L1","kw":["田獲三品","收穫","功勞","大吉"],"i":["順勢而為，收穫豐富（三品），立大功","多種療法並用，效果顯著","付出得到回報，感情收穫滿滿","多方進財，財源廣進","投資組合全面獲利，大豐收","遇到多種好對象，滿載而歸","勝訴，遇到多重賠償","買到增值潛力大的地產，或收租豐富"]},"57-5":{"name":"九五","text":"貞吉，悔亡，无不利。无初有終，先庚三日，後庚三日，吉","level":"L2","kw":["先庚","後庚","計畫","改革"],"i":["初期不順，但做好周密計畫（前後三日），改革成功","治療計畫周詳，最終康復","開始有波折，但經過溝通調整，結局圓滿","規劃好理財計畫，執行後大賺","深思熟慮後進場，獲利豐厚","充分了解對方後再婚,較能美滿","準備充分，先輸後贏","仔細評估後買房，增值"]},"57-6":{"name":"上九","text":"巽在床下，喪其資斧，貞凶","level":"L8","kw":["床下","喪資","過度","凶"],"i":["過度卑躬屈膝，反而失去尊嚴和權力（資斧），凶","臥床不起，喪失行動能力","卑微到塵埃裡，失去自我，被拋棄","破財，連本金都沒了","猶豫不決導致資金全被套牢","感情受騙損失慘重，或遇到虛情假意之人","失去籌碼，必敗","失去房產，無家可歸"]},"58-1":{"name":"初九","text":"和兌，吉","level":"L1","kw":["和兌","平和","吉","溝通"],"i":["人際關係和諧，溝通順暢，大吉","心情愉快，身體健康","相處融洽，和和美美","和氣生財，財運好","心態平和，獲利自然來","相處愉快，遇到良緣","和解，雙方滿意","鄰里和睦，居住舒適"]},"58-2":{"name":"九二","text":"孚兌，吉，悔亡","level":"L2","kw":["孚兌","誠信","吉","真心"],"i":["以誠信待人，遇到信任，吉","相信醫生，配合治療，康復","真心相愛，沒有欺騙，吉","講信用，生意興隆","相信自己的判斷，獲利","長輩誠實，婚姻優良","誠實陳述，遇到有利判決","交易透明，買賣雙方互信"]},"58-3":{"name":"六三","text":"來兌，凶","level":"L7","kw":["來兌","巴結","凶","虛偽"],"i":["刻意巴結討好，心術不正，凶","尋歡作樂傷身，或聽信偏方","爛桃花，對方為了利益而來，凶","被花言巧語詐騙，破財","聽信明牌，慘賠","被甜言蜜語者洗腦，陷入不良關係","被對方收買或欺騙，凶","仲介花言巧語，買到瑕疵屋"]},"58-4":{"name":"九四","text":"商兌，未寧，介疾有喜","level":"L3","kw":["商兌","未寧","介疾","協商"],"i":["正在協商中，心神不寧，但隔絕壞人後會有喜","心理焦慮，排除干擾後好轉","猶豫是否接受對方，下定決心拒絕爛桃花就有喜","商業談判進行中，堅持原則有利","猶豫買賣，排除雜念後獲利","斤斤計較中，最終成交","談判和解中，有喜訊","議價過程中，最終有好結果"]},"58-5":{"name":"九五","text":"孚于剝，有厲","level":"L6","kw":["孚于剝","錯信","小人","危險"],"i":["信任小人（剝），將被剝奪權力，危險","身體被病毒侵蝕，或誤信庸醫","愛上不該愛的人，被騙財騙色","被詐騙集團騙走積蓄，危險","相信假消息，接盤被套","遇到金玉其外敗絮其中的婚姻","證人做偽證，危險","房屋有白蟻或結構被侵蝕"]},"58-6":{"name":"上六","text":"引兌","level":"L5","kw":["引兌","牽引","誘惑","未定"],"i":["受到誘惑，不知去向，吉凶未定（看定力）","沈迷聲色犬馬，可能傷身","受到對方引誘，可能出軌或沈淪","受到高利誘惑，小心詐騙","盲目跟風，風險大","被廣告吸引，衝動決定大事","被對方引導，可能陷入圈套","被外觀吸引，忽略內在問題"]},"59-1":{"name":"初六","text":"用拯馬壯，吉","level":"L2","kw":["拯馬","救援","吉","迅速"],"i":["危機剛開始就迅速救援，吉","急症發作，救護車迅速送醫，吉","誤會剛產生就迅速解釋，挽回感情","財務破洞迅速補上，吉","見勢頭不對迅速撤離，保本","發展關係錯關係迅速分合","迅速尋求法律援助，吉","房子問題迅速修繕，吉"]},"59-2":{"name":"九二","text":"渙奔其机，悔亡","level":"L3","kw":["奔机","依靠","避難","安身"],"i":["局勢動盪，迅速找到依靠（如大樹、後台），悔亡","身體虛弱，找到好的支撐點（療法）","感情受傷，回到家人或朋友身邊尋求慰藉","市場崩盤，持有現金為王（机）","避開風險資產，轉入避險資產","遇到實用的傢俱或支撐物","找到有力的依靠或證據","買到地基穩固的房子，安居"]},"59-3":{"name":"六三","text":"渙其躬，无悔","level":"L4","kw":["渙躬","犧牲","无悔","忘我"],"i":["犧牲小我完成大我，雖有損失但無悔","捐獻器官或血液，或者為了工作透支身體（需注意）","全心全意付出，不求回報","捐款助人，散財消災","為了大局停損，無悔","付出感情給他人，自己沒用但開心","承認部分過失以換取和解","為了還債賣房，無悔"]},"59-4":{"name":"六四","text":"渙其群，元吉。渙有丘，匪夷所思","level":"L1","kw":["渙群","大吉","匪夷所思","奇蹟"],"i":["解散小團體，團結大組織，遇到意想不到的成功","擴散的癌細胞或病菌被清除，奇蹟康復","擺脫爛桃花，遇到意想不到的好對象","散盡家財做公益，反而遇到更大的財富","打破常規，遇到不可思議的獲利","遇到意想不到的奇珍異寶","瓦解對方的攻勢，大勝","買到增值潛力驚人的土地"]},"59-5":{"name":"九五","text":"渙汗其大號，渙王居，无咎","level":"L2","kw":["渙汗","大號","政令","改革"],"i":["發布重大命令，改革弊端，如出汗排毒，無咎","發一身大汗，病癒","大聲說出愛，消除隔閡","宣布重大投資計畫，股價大漲","跟隨政策方向，獲利","發展關係名門或官方認證婚姻","官方發布有利解釋，勝訴","政府重大建設利多，房價漲"]},"59-6":{"name":"上九","text":"渙其血，去逖出，无咎","level":"L3","kw":["渙血","去逖","遠離","避害"],"i":["遠離血腥鬥爭，明哲保身，無咎","防止出血，或遠離傳染源，保平安","遠離恐怖情人，避免流血衝突","遠離高風險投資，保住本金","在崩盤前離場，毫髮無傷","不發展關係危險品，遠離糾紛","避免訴訟升級為流血衝突，和解吉","遠離危險地帶（如斷層、土石流區）"]},"60-1":{"name":"初九","text":"不出戶庭，无咎","level":"L3","kw":["不出戶","慎始","无咎","保密"],"i":["時機未到，閉門修練，不輕易出擊，無咎","居家隔離，不出門，避免感染","宅在家裡，暫不談戀愛，或地下情不公開","財不露白，錢財留在家裡","觀望，不進場操作","網路交友或不發展關係，不出門避免損失","庭外和解，不把事情鬧大","守著祖產，不賣"]},"60-2":{"name":"九二","text":"不出門庭，凶","level":"L7","kw":["不出門","錯失","凶","自閉"],"i":["該出擊不出擊，錯失良機，凶","該就醫不就醫，拖延病情，凶","自閉不社交，錯過良緣，孤獨","錯失投資良機，錢放著貶值","該賣不賣，錯過高點，凶","該出手時未出手，錯失良緣後悔","不到庭應訊，缺席判決敗訴","該賣不賣，房價跌了"]},"60-3":{"name":"六三","text":"不節若，則嗟若，无咎","level":"L5","kw":["不節","嗟若","後悔","自作自受"],"i":["不知節制，放縱自己，失敗後嘆息，怪誰呢？","飲食無度，生病了才後悔","縱慾過度，身體搞壞或感情破裂，嘆息","揮霍無度，沒錢了才嘆氣","貪得無厭，不亦樂乎，結果一場空","刷爆卡，收到帳單才嘆氣","不知收斂，導致敗訴","過度裝修過度，後悔"]},"60-4":{"name":"六四","text":"安節，亨","level":"L2","kw":["安節","自然","亨","舒適"],"i":["安分守己，制度合理，大家做得開心，亨通","生活規律，飲食有節，身心安泰","感情穩定，細水長流，相處舒服","理財有道，穩健增長，安心","穩健操作，獲利令人安心","適度交往，關係健康","遵守法律，平安無事","居住安適，風水好"]},"60-5":{"name":"九五","text":"甘節，吉，往有尚","level":"L1","kw":["甘節","快樂","吉","美德"],"i":["節制得當，大家都覺得甜美願意遵守，大吉","養生飲食美味又健康，樂在其中","甜蜜的約束，雙方都享受這份關係","儲蓄帶來快樂，財富累積","停利點設得好，落袋為安，快樂","發展關係得剛剛好，找到理想伴侶","和解條件優渥，雙方滿意","買到性價比極高的房子"]},"60-6":{"name":"上六","text":"苦節，貞凶，悔亡","level":"L8","kw":["苦節","苛刻","凶","極端"],"i":["規定太嚴苛，沒人受得了，凶","過度節食或苦行，搞壞身體","管得太嚴，對方受不了逃跑","省錢省到虐待自己，守財奴，凶","設定太嚴苛的條件，完全無法交易","太摳門，生活人品極差","得理不饒人，逼人太甚，凶","對房客太苛刻，惹麻煩"]},"61-1":{"name":"初九","text":"虞吉，有它不燕","level":"L3","kw":["虞","專一","不燕","安寧"],"i":["專心致志，不三心二意，吉","靜心休養，不被雜事干擾","專情於一人，吉，花心則不安","專注本業，不投機取巧","專注於熟悉的領域，吉","發展關係需要的就好，不貪多","立場堅定，不被動搖","安居樂業，不宜搬遷"]},"61-2":{"name":"九二","text":"鳴鶴在陰，其子和之，我有好爵，吾與爾靡之","level":"L2","kw":["鳴鶴","和之","共鳴","好爵"],"i":["有真才實學，雖在低位也能引起共鳴，遇到美酒（職位）","身心和諧，母子平安","心靈相通，琴瑟和鳴，感情極佳","與人分享財富，共創雙贏","市場對你的看法有共鳴，獲利","遇到好酒或好對象，與朋友分享","雙方達成共識，和解","鄰里關係和諧，居住愉快"]},"61-3":{"name":"六三","text":"得敵，或鼓或罷，或泣或歌","level":"L6","kw":["得敵","情緒化","無常","失控"],"i":["情緒失控，一會兒努力一會兒放棄，事業無成","躁鬱症，情緒起伏過大","愛恨交織，一會兒哭一會兒笑，折磨","財運起伏不定，大賺大賠","追高殺跌，情緒化操作，虧損","衝動決定大事後又後悔","在法庭上情緒失控，不利","買賣反覆無常，談不成"]},"61-4":{"name":"六四","text":"月幾望，馬匹亡，无咎","level":"L2","kw":["月望","馬亡","犧牲","忠誠"],"i":["犧牲小我（馬匹），效忠上級，無咎，前途光明","犧牲一點享受，換來健康","為了對方犧牲自己的利益，感情升溫","損失小財，換取大機會","賣掉落後股，換入強勢股","退掉不合適的，發展關係更好的","捨車保帥，無咎","賣掉舊房換新房"]},"61-5":{"name":"九五","text":"有孚攣如，无咎","level":"L1","kw":["攣如","緊密","誠信","團結"],"i":["與團隊緊密團結，互信互助，事業大成","免疫系統強大，緊密防護","如膠似漆，分不開，感情極佳","合作夥伴關係緊密，財源穩固","資產配置緊密合理，無懈可擊","遇到結構緊密紮實的良緣","證據鏈緊密，勝訴","房子結構堅固，家人團結"]},"61-6":{"name":"上九","text":"翰音登于天，貞凶","level":"L8","kw":["翰音","虛名","凶","不實"],"i":["名不副實，吹牛吹上天，最終跌落，凶","虛火上升，外強中乾","甜言蜜語，沒有實際行動，感情破裂","吹噓財富，其實負債累累","泡沫化，股價虛高，即將崩盤","廣告不實，遇到爛關係","虛張聲勢，最終敗訴","房價炒作過高，有行無市"]},"62-1":{"name":"初六","text":"飛鳥以凶","level":"L7","kw":["飛鳥","好高騖遠","凶","躁進"],"i":["能力不足卻想飛高，好高騖遠，必敗","不自量力，過度運動受傷","追求高不可攀的對象，自取其辱","想賺快錢，結果賠光","新手想玩高槓桿，凶","發展關係不起硬買，卡債纏身","小案子搞成大官司，不利","買不起豪宅硬買，斷頭"]},"62-2":{"name":"六二","text":"過其祖，遇其妣，不及其君，遇其臣，无咎","level":"L4","kw":["過祖遇妣","不及君","遇臣","低調"],"i":["越級報告不妥，向下紮根，找副手談吉","不需找名醫，找普通醫生即可","不追求高富帥，找門當戶對或稍低的對象","不求暴富，賺小錢無咎","不買龍頭股，買二線股無咎","不發展關係頂級款，買次級款實用","私下和解，不上法院","買小房子或低樓層，無咎"]},"62-3":{"name":"九三","text":"弗過防之，從或戕之，凶","level":"L8","kw":["弗過","戕之","疏忽","被害"],"i":["自以為是，疏於防範，被小人暗算，凶","疏於保養，突發急病","太過自信，對方劈腿了都不知道","不設防，被詐騙或遭竊","不設停損，慘遭殺戮","遇到危險對象受傷","被人反告，措手不及","居家安全沒做好，遭竊"]},"62-4":{"name":"九四","text":"无咎，弗過遇之。往厲必戒，勿用永貞","level":"L5","kw":["往厲","戒備","勿用","保守"],"i":["位高權重但處境危險，保持低調，不強出頭則無咎","身體虛弱，不可勉強，需長期調養","保持距離，不可太過熱情，否則有危險","守財為主，不可擴張","市場險惡，觀望為宜","此時不宜發展關係，靜待時機為上","防守為主，不主動攻擊","暫時不買賣，觀望"]},"62-5":{"name":"六五","text":"密雲不雨，自我西郊，公弋取彼在穴","level":"L4","kw":["密雲不雨","弋取","隱士","求賢"],"i":["局勢晦暗不明，無法大展身手，只能做些小事或提拔新人","陰虛火旺，心情悶悶不樂","曖昧不明，沒有結果，只能找替代品","雷聲大雨點小，賺不到大錢","行情悶，抓抓短線小魚","尋找很久未遇理想對象，只有小緣分","拖延不決，只能抓到小辮子","房市膠著，只能買到小房子"]},"62-6":{"name":"上六","text":"弗遇過之，飛鳥離之，凶，是謂災眚","level":"L9","kw":["飛鳥離","過高","災眚","毀滅"],"i":["好大喜功，飛得太高摔得粉身碎骨，大凶","過度透支，猝死或重病","要求太高，孤獨終老，或遭遇情劫","貪得無厭，傾家蕩產","瘋狂追高，崩盤歸零","過度投入感情，難以自拔，終致崩潰","不知進退，招致大禍","炒房失敗，負債累累"]},"63-1":{"name":"初九","text":"曳其輪，濡其尾，无咎","level":"L3","kw":["曳輪","濡尾","謹慎","煞車"],"i":["事情剛完成，要放慢腳步，小心謹慎，無咎","病癒初期，不可太累，小心調養","剛結婚或剛交往，要小心經營，不可大意","賺了錢要守住，煞車不亂花","獲利了結，暫時休息","婚姻需謹慎,暫緩為宜","剛勝訴，不要得意忘形，小心對方反撲","剛買房，裝修要謹慎，不要過度"]},"63-2":{"name":"六二","text":"婦喪其茀，勿逐，七日得","level":"L4","kw":["喪茀","勿逐","失而復得","等待"],"i":["失去保護或地位，不要急著爭取，過陣子會恢復","頭髮脫落或皮膚問題，過陣子會好","失去對方的寵愛，不要吵，過陣子會好","小破財，不要追，會賺回來","暫時套牢，不要殺低，會回升","感情中斷，不要急，會復合","暫時失利，等待轉機","錯失好房，不要急，會有更好的"]},"63-3":{"name":"九三","text":"高宗伐鬼方，三年克之，小人勿用","level":"L4","kw":["伐鬼方","三年","艱苦","小人勿用"],"i":["雖能完成艱鉅任務，但耗時費力（三年），不可用小人","治療慢性頑疾，需長期抗戰","追求過程極其艱辛，需長跑多年","賺辛苦錢，長期累積","長期投資，過程波折","建立了需要長期經營的關係","長期抗戰，精疲力盡","老屋翻修，耗時費力"]},"63-4":{"name":"六四","text":"繻有衣袽，終日戒","level":"L5","kw":["衣袽","破衣","防漏","警戒"],"i":["成功後隱患浮現，需隨時修補漏洞，整日警戒","身體虛弱，需隨時保暖防病","感情出現裂痕，需小心修補","財務出現漏洞，需隨時補救","市場風險大，隨時準備逃命","遇到有缺陷的對象，勉強修補使用","案情有漏洞，需小心防範","房子漏水，需修補"]},"63-5":{"name":"九五","text":"東鄰殺牛，不如西鄰之禴祭，實受其福","level":"L2","kw":["殺牛","禴祭","誠心","實惠"],"i":["鋪張浪費不如誠心實意，簡約反而受福","吃大補品不如清淡飲食","奢華婚禮不如真心相待","小本經營，誠信獲利，勝過大財團","小額定期定額，勝過大額投機","發展關係實用條件差的對象，勝過名門","誠實以對，勝過花大錢請律師","溫馨小屋勝過冰冷豪宅"]},"63-6":{"name":"上六","text":"濡其首，厲","level":"L8","kw":["濡首","滅頂","過度","危險"],"i":["成功後得意忘形，最終滅頂，危險","酗酒或沈迷慾望，傷身","沈溺於感情，失去理智，危險","揮霍無度，最終破產","貪婪不走，最終被套牢滅頂","遇到剁手，陷入困境","不知進退，惹禍上身","房貸過重，面臨法拍"]},"64-1":{"name":"初六","text":"濡其尾，吝","level":"L5","kw":["濡尾","不知量力","受阻","羞恥"],"i":["工作剛開始就遇到挫折，能力不足，羞愧","身體虛弱，想運動卻力不從心","剛開始追求就碰壁，丟臉","想創業資金不足，起步維艱","進場就虧損，懊惱","條件不足硬要發展關係，條件不符","一開始就處於劣勢","頭期款不足，買房受阻"]},"64-2":{"name":"九二","text":"曳其輪，貞吉","level":"L3","kw":["曳輪","拖延","等待","中正"],"i":["時機未到，放慢腳步，自我修練，吉","不宜劇烈運動，慢活養生，吉","不急於結婚，慢慢培養感情，吉","不急著賺錢，累積實力","觀望，等待最佳買點","暫緩交往，多方考察","拖延戰術，以靜制動","不急著買賣，多看多比較"]},"64-3":{"name":"六三","text":"未濟，征凶，利涉大川","level":"L5","kw":["未濟","征凶","冒險","改變"],"i":["現狀不佳，強行前進凶，適合轉換跑道","病情未癒，不宜出遠門","感情未成熟，強求結果凶","投資虧損，不宜加碼","趨勢未明，進場凶","沒看到喜歡的，不要勉強發展關係","時機不利，興訟凶","條件未談攏，簽約凶"]},"64-4":{"name":"九四","text":"貞吉，悔亡，震用伐鬼方，三年有賞于大國","level":"L2","kw":["伐鬼方","三年","奮鬥","封賞"],"i":["經過長期奮鬥（三年），終於克服困難，遇到大獎賞","長期治療，終於戰勝病魔","愛情長跑，終於修成正果","長期投資，終於獲利翻倍","堅持到底，獲得豐厚回報","等待很久，終於遇到理想對象","長期訴訟，終於勝訴","長期還貸，終於擁有自己的房子"]},"64-5":{"name":"六五","text":"貞吉，无悔，君子之光，有孚，吉","level":"L1","kw":["君子光","有孚","輝煌","信任"],"i":["光彩照人，領袖魅力，眾人信任，大吉","精神飽滿，神采飛揚","魅力四射，感情美滿，吉","信譽卓著，財源廣進","眼光獨到，獲利驚人","遇到光彩奪目的好對象","光明正大，勝訴","買到採光極佳的豪宅"]},"64-6":{"name":"上九","text":"有孚于飲酒，无咎，濡其首，有孚失是","level":"L6","kw":["飲酒","濡首","節制","縱樂"],"i":["成功後飲酒慶祝無咎，但若沈迷其中則失去原則","適度飲酒養生，過度則傷身","享受浪漫無妨，但不可沈溺情慾","享受財富無妨，但不可揮霍","賺錢後犒賞自己無妨，但不可得意忘形","適度婚姻無妨，刷爆卡則糟","勝訴慶祝無妨，但不可侮辱對方","喬遷之喜無妨，但不可擾鄰"]}};
